export const PROPOSTA_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Gerador de Proposta</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo+Black&family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    /* tokens da folha/PDF — não alterar, define o documento impresso */\n    --paper:#F5F1E6;\n    --paper-dark:#EDE7D8;\n    --ink:#17140F;\n    --ink-soft:#5B5646;\n    --line:#CBC1A6;\n    --panel:#FFFDF8;\n\n    /* tokens do painel de edição (tela) */\n    --bg:#0A0B0D;\n    --dpanel:#131519;\n    --dpanel-2:#1B1E23;\n    --dline:#262A30;\n    --dtext:#E8EAED;\n    --dtext-soft:#7D848C;\n    --accent:#FF3B30;\n    --accent-dim:rgba(255,59,48,.14);\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:var(--bg);\n    font-family:'Space Grotesk',sans-serif;\n    color:var(--dtext);\n  }\n  .app{\n    display:grid;\n    grid-template-columns:380px 1fr;\n    min-height:100vh;\n  }\n  /* ---------- EDITOR ---------- */\n  .editor{\n    background:var(--dpanel);\n    padding:28px 26px 100px;\n    border-right:1px solid var(--dline);\n    overflow-y:auto;\n    max-height:100vh;\n  }\n  .editor h1{\n    font-size:19px;\n    font-weight:700;\n    letter-spacing:-.01em;\n    margin:0 0 4px;\n  }\n  .editor p.sub{\n    margin:0 0 24px;\n    font-size:12px;\n    color:var(--dtext-soft);\n    line-height:1.6;\n  }\n  .group{margin-bottom:22px;}\n  .group h2{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10.5px;\n    text-transform:uppercase;\n    letter-spacing:.14em;\n    color:var(--dtext-soft);\n    margin:0 0 10px;\n    padding-bottom:8px;\n    border-bottom:1px solid var(--dline);\n    display:flex;\n    align-items:center;\n    gap:8px;\n  }\n  .group h2:before{\n    content:'';\n    width:5px;height:5px;\n    border-radius:50%;\n    background:var(--dline);\n  }\n  label{\n    display:block;\n    font-size:11px;\n    color:var(--dtext-soft);\n    margin:10px 0 5px;\n  }\n  input[type=text],textarea{\n    width:100%;\n    font-family:'Space Grotesk',sans-serif;\n    font-size:13px;\n    padding:8px 10px;\n    border:1px solid var(--dline);\n    border-radius:6px;\n    background:var(--dpanel-2);\n    color:var(--dtext);\n  }\n  input[type=number]{\n    width:100%;\n    font-family:'JetBrains Mono',monospace;\n    font-size:13px;\n    padding:8px 10px;\n    border:1px solid var(--dline);\n    border-radius:6px;\n    background:var(--dpanel-2);\n    color:var(--dtext);\n  }\n  input:focus,textarea:focus{outline:none;border-color:var(--accent);}\n  .row2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n  .list-item{\n    display:flex;\n    gap:6px;\n    margin-bottom:6px;\n  }\n  .list-item input{flex:1;}\n  .list-item button, .add-btn{\n    cursor:pointer;\n    font-family:'JetBrains Mono',monospace;\n    font-weight:600;\n    border:1px solid var(--dline);\n    background:transparent;\n    color:var(--dtext-soft);\n    border-radius:6px;\n  }\n  .list-item button{\n    width:30px;\n    font-size:16px;\n    line-height:1;\n    transition:.15s;\n  }\n  .list-item button:hover{border-color:var(--accent);color:var(--accent);}\n  .add-btn{\n    margin-top:2px;\n    padding:8px 12px;\n    font-size:11.5px;\n    letter-spacing:.03em;\n    text-transform:uppercase;\n    border-style:dashed;\n    width:100%;\n    transition:.15s;\n  }\n  .add-btn:hover{border-color:var(--accent);color:var(--accent);}\n  .print-btn{\n    position:fixed;\n    bottom:24px;\n    left:26px;\n    width:328px;\n    padding:14px;\n    font-size:12.5px;\n    font-family:'JetBrains Mono',monospace;\n    font-weight:600;\n    text-transform:uppercase;\n    letter-spacing:.05em;\n    cursor:pointer;\n    border:1px solid var(--accent);\n    background:var(--accent-dim);\n    color:var(--dtext);\n    border-radius:8px;\n    box-shadow:0 6px 20px rgba(255,59,48,.15);\n    transition:.15s;\n  }\n  .print-btn:hover{background:var(--accent);color:#fff;}\n  details.fixed{margin-top:6px;}\n  details.fixed summary{\n    cursor:pointer;\n    font-size:11.5px;\n    color:var(--dtext-soft);\n  }\n\n  /* ---------- PREVIEW ---------- */\n  .preview-wrap{\n    padding:40px;\n    display:flex;\n    justify-content:center;\n    align-items:flex-start;\n  }\n  .sheet{\n    width:720px;\n    min-height:1000px;\n    background:var(--paper);\n    background-image:radial-gradient(circle at 1px 1px, rgba(0,0,0,.035) 1px, transparent 0);\n    background-size:14px 14px;\n    padding:64px 60px 0;\n    box-shadow:0 20px 50px rgba(0,0,0,.28);\n    position:relative;\n    color:var(--ink);\n  }\n  .slate{\n    position:absolute;\n    top:0; right:64px;\n    background:var(--ink);\n    color:var(--paper);\n    font-family:'Archivo Black',sans-serif;\n    font-size:11px;\n    letter-spacing:.08em;\n    padding:8px 14px;\n    transform:translateY(-1px);\n  }\n  .head{\n    display:flex;\n    justify-content:space-between;\n    align-items:flex-start;\n    margin-bottom:36px;\n  }\n  .head h1{\n    font-family:'Archivo Black',sans-serif;\n    font-size:44px;\n    line-height:0.9;\n    margin:0;\n  }\n  .head .titulo{\n    font-family:'Archivo Black',sans-serif;\n    font-size:15px;\n    letter-spacing:.02em;\n    margin-top:10px;\n  }\n  .head .data{\n    font-size:12px;\n    color:var(--ink-soft);\n    margin-top:4px;\n  }\n  .logo{\n    text-align:right;\n  }\n  .logo img{\n    height:34px;\n    width:auto;\n    display:block;\n    margin-left:auto;\n  }\n  .logo .tag{\n    display:none;\n  }\n  .valor-linha{\n    display:flex;\n    justify-content:space-between;\n    gap:12px;\n    font-size:13px;\n    padding:8px 0;\n    border-top:1px solid var(--line);\n  }\n  .valor-linha .v{\n    white-space:nowrap;\n    color:var(--ink-soft);\n  }\n  .pagamento{\n    font-size:12.5px;\n    color:var(--ink-soft);\n    text-align:center;\n    padding:0 20px 22px;\n    line-height:1.6;\n  }\n  .pagamento.hidden{display:none;}\n  .pagamento b{color:var(--ink);font-weight:600;}\n  .info-columns{\n    display:flex;\n    gap:26px;\n    margin-bottom:34px;\n  }\n  .info-col{\n    flex:1 1 0;\n    font-size:12.5px;\n    line-height:1.85;\n  }\n  .info-col.full{flex:1 1 100%;}\n  .info-col.hidden{display:none;}\n  .info-col .name{\n    font-weight:700;\n    font-size:14px;\n    display:block;\n    margin-bottom:6px;\n  }\n  .info-col b{font-weight:600;color:var(--ink-soft);}\n  .info-divider{\n    width:1px;\n    background:var(--line);\n    flex:0 0 1px;\n  }\n  .info-divider.hidden{display:none;}\n  .info-columns.empty{display:none;}\n  .section{margin-bottom:8px;}\n  .section h2{\n    font-family:'Archivo Black',sans-serif;\n    font-size:16px;\n    margin:0 0 14px;\n  }\n  .section ul{\n    list-style:none;\n    margin:0 0 26px;\n    padding:0;\n  }\n  .section li{\n    font-size:13.5px;\n    line-height:1.55;\n    padding:9px 0 9px 22px;\n    position:relative;\n    border-top:1px solid var(--line);\n  }\n  .section li:before{\n    content:\"•\";\n    position:absolute;\n    left:2px;\n    font-size:16px;\n    line-height:1;\n    color:var(--ink-soft);\n  }\n  .rule{border:none;border-top:1px solid var(--line);margin:0 0 26px;}\n  .total{\n    text-align:center;\n    padding:22px 0 8px;\n  }\n  .total .label{\n    font-size:12px;\n    letter-spacing:.1em;\n    text-transform:uppercase;\n    color:var(--ink-soft);\n  }\n  .total .value{\n    font-family:'Archivo Black',sans-serif;\n    font-size:38px;\n    margin-top:6px;\n  }\n  .toggle-row{\n    display:flex;\n    align-items:center;\n    gap:10px;\n    margin:12px 0;\n  }\n  .toggle-row label{\n    margin:0;\n    font-size:12px;\n    color:var(--dtext);\n    flex:1;\n  }\n  .switch{position:relative;width:34px;height:19px;flex:0 0 auto;cursor:pointer;}\n  .switch input{position:absolute;opacity:0;width:100%;height:100%;margin:0;cursor:pointer;z-index:2;}\n  .switch .track{position:absolute;inset:0;background:var(--dpanel-2);border:1px solid var(--dline);border-radius:20px;transition:.15s;}\n  .switch .thumb{position:absolute;top:2px;left:2px;width:13px;height:13px;border-radius:50%;background:var(--dtext-soft);transition:.15s;}\n  .switch input:checked + .track{background:var(--accent-dim);border-color:var(--accent);}\n  .switch input:checked ~ .thumb{transform:translateX(15px);background:var(--accent);}\n  .footer{\n    background:var(--ink);\n    color:var(--paper);\n    text-align:center;\n    font-size:12px;\n    letter-spacing:.04em;\n    padding:16px;\n    margin:0 -60px;\n  }\n\n  @media print{\n    @page{ size:A4; margin:10mm; }\n    *{\n      -webkit-print-color-adjust: exact !important;\n      print-color-adjust: exact !important;\n      color-adjust: exact !important;\n    }\n    body{background:#fff;}\n    .editor,.print-btn{display:none !important;}\n    .app{display:block;}\n    .preview-wrap{padding:0;display:block;}\n    html,body{height:100%;}\n    .sheet{box-shadow:none;width:190mm;height:277mm;min-height:277mm;margin:0 auto;padding:14mm 14mm 0;display:flex;flex-direction:column;}\n    .slate{top:-6px;}\n    .head{margin-bottom:20px;}\n    .head h1{font-size:36px;}\n    .logo img{height:28px;}\n    .info-columns{margin-bottom:18px;}\n    .info-col{font-size:11.5px;line-height:1.55;}\n    .section h2{margin-bottom:8px;font-size:14px;}\n    .section ul{margin-bottom:14px;}\n    .section li{padding:6px 0 6px 20px;font-size:12px;}\n    .rule{margin-bottom:14px;}\n    .total{padding:10px 0 2px;}\n    .total .value{font-size:30px;}\n    .pagamento{padding-bottom:12px;}\n    .footer{margin:auto -14mm 0;padding:10px;}\n  }\n  @media (max-width:860px){\n    .app{grid-template-columns:1fr;}\n    .editor{max-height:none;border-right:none;border-bottom:1px solid var(--dline);}\n    .print-btn{position:static;width:100%;margin-top:16px;}\n    .sheet{width:100%;padding:36px 24px 0;}\n    .footer{margin:0 -24px;}\n  }\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <!-- ================= EDITOR ================= -->\n  <div class=\"editor\">\n    <h1>Gerador de Proposta</h1>\n    <p class=\"sub\">Preencha os dados abaixo — a proposta ao lado se atualiza sozinha. Depois clique em \"Baixar PDF\".</p>\n\n    <div class=\"group\" id=\"grupo-numeracao\">\n      <h2>Numeração</h2>\n      <label>Nº desta proposta</label>\n      <input type=\"text\" id=\"in-numero\" value=\"001\">\n      <p style=\"font-size:11px;color:var(--dtext-soft);margin:6px 0 0;\">Na proposta aparece como <b>Nº/mês.ano</b>, ex: 001.07/26 — o mês/ano é puxado automaticamente do campo \"Data\" abaixo.</p>\n      <button class=\"add-btn\" style=\"margin-top:8px;\" onclick=\"confirmarNumero()\">✓ Confirmar e reservar este número</button>\n      <p style=\"font-size:11px;color:var(--dtext-soft);margin:8px 0 0;\">Ao clicar em \"Confirmar\", este número fica registrado neste navegador e a próxima proposta já sugere o seguinte. Se só estiver testando ou corrigindo algo, não precisa confirmar.</p>\n    </div>\n\n    <div class=\"group\">\n      <h2>Projeto</h2>\n      <label>Título</label>\n      <input type=\"text\" id=\"in-titulo\" value=\"Produção de Podcast\">\n      <label>Tipo de produção</label>\n      <select id=\"in-tipo-producao\" style=\"width:100%;font-family:'Space Grotesk',sans-serif;font-size:13px;padding:8px 10px;border:1px solid var(--dline);border-radius:6px;background:var(--dpanel-2);color:var(--dtext);\" onchange=\"aplicarTemplateTipoProducao()\">\n        <option>Produção Comercial</option>\n        <option>Institucional</option>\n        <option>Podcast</option>\n        <option>Produção de Conteúdo</option>\n        <option>Motion</option>\n        <option>Outro</option>\n      </select>\n      <label>Data</label>\n      <input type=\"text\" id=\"in-data\" value=\"09/07/2026\">\n    </div>\n\n    <div class=\"group\">\n      <h2>Cliente</h2>\n      <div class=\"toggle-row\">\n        <label for=\"chk-cliente\">Incluir dados do cliente na proposta</label>\n        <div class=\"switch\"><input type=\"checkbox\" id=\"chk-cliente\" checked onchange=\"atualizarColunas()\"><div class=\"track\"></div><div class=\"thumb\"></div></div>\n      </div>\n      <label>Selecionar cliente do painel (opcional)</label>\n      <select id=\"in-cliente-selecionar\" style=\"width:100%;font-family:'Space Grotesk',sans-serif;font-size:13px;padding:8px 10px;border:1px solid var(--dline);border-radius:6px;background:var(--dpanel-2);color:var(--dtext);margin-bottom:14px;\" onchange=\"preencherClienteSelecionado()\">\n        <option value=\"\">— Selecionar —</option>\n      </select>\n      <label>Nome fantasia</label>\n      <input type=\"text\" id=\"in-cli-nome\" value=\"\">\n      <label>Razão social</label>\n      <input type=\"text\" id=\"in-cli-razao\" value=\"\">\n      <label>Endereço</label>\n      <input type=\"text\" id=\"in-cli-endereco\" value=\"\">\n      <div class=\"row2\">\n        <div><label>Bairro</label><input type=\"text\" id=\"in-cli-bairro\" value=\"\"></div>\n        <div><label>Município</label><input type=\"text\" id=\"in-cli-municipio\" value=\"\"></div>\n      </div>\n      <div class=\"row2\">\n        <div><label>Estado</label><input type=\"text\" id=\"in-cli-estado\" value=\"\"></div>\n        <div><label>CEP</label><input type=\"text\" id=\"in-cli-cep\" value=\"\"></div>\n      </div>\n      <div class=\"row2\">\n        <div><label>Telefone</label><input type=\"text\" id=\"in-cli-telefone\" value=\"\"></div>\n        <div><label>CNPJ</label><input type=\"text\" id=\"in-cli-cnpj\" value=\"\"></div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Marca / Cabeçalho</h2>\n      <div class=\"toggle-row\">\n        <label for=\"chk-logo\">Exibir logo da fuzz no cabeçalho</label>\n        <div class=\"switch\"><input type=\"checkbox\" id=\"chk-logo\" checked onchange=\"atualizarLogo()\"><div class=\"track\"></div><div class=\"thumb\"></div></div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Dados da fuzz na proposta</h2>\n      <div class=\"toggle-row\">\n        <label for=\"chk-fuzzdados\">Incluir dados da fuzz na proposta (alguns clientes exigem)</label>\n        <div class=\"switch\"><input type=\"checkbox\" id=\"chk-fuzzdados\" onchange=\"atualizarColunas()\"><div class=\"track\"></div><div class=\"thumb\"></div></div>\n      </div>\n      <label>Nome fantasia</label>\n      <input type=\"text\" id=\"in-fuzz-nome\" value=\"Fuzz Filmes\">\n      <label>Razão social</label>\n      <input type=\"text\" id=\"in-fuzz-razao\" value=\"FUZZ PRODUTORA DE VÍDEOS\">\n      <label>Endereço</label>\n      <input type=\"text\" id=\"in-fuzz-endereco\" value=\"Rua Goiás, 369 - Apto 1005, Bairro Assis Brasil, Ijuí/RS - CEP: 98700-000\">\n      <div class=\"row2\">\n        <div><label>Telefone</label><input type=\"text\" id=\"in-fuzz-telefone\" value=\"(55) 99147-8685\"></div>\n        <div><label>CNPJ</label><input type=\"text\" id=\"in-fuzz-cnpj\" value=\"33.811.775/0001-04\"></div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Produção</h2>\n      <div id=\"lista-producao\"></div>\n      <button class=\"add-btn\" onclick=\"addItem('producao')\">+ adicionar item</button>\n    </div>\n\n    <div class=\"group\">\n      <h2>Entrega</h2>\n      <div id=\"lista-entrega\"></div>\n      <button class=\"add-btn\" onclick=\"addItem('entrega')\">+ adicionar item</button>\n    </div>\n\n    <div class=\"group\">\n      <h2>Investimento</h2>\n      <div class=\"toggle-row\">\n        <label for=\"chk-detalhar\">Detalhar valores em itens (captação, edição, deslocamento...)</label>\n        <div class=\"switch\"><input type=\"checkbox\" id=\"chk-detalhar\" onchange=\"atualizarModoValor()\"><div class=\"track\"></div><div class=\"thumb\"></div></div>\n      </div>\n\n      <div id=\"bloco-valor-simples\">\n        <label>Valor total (R$)</label>\n        <input type=\"text\" id=\"in-valor\" value=\"550,00\" oninput=\"recalcularTotal()\">\n      </div>\n\n      <div id=\"bloco-valor-itens\" style=\"display:none;\">\n        <div id=\"lista-investimento\"></div>\n        <button class=\"add-btn\" onclick=\"addItemInvestimento()\">+ adicionar item</button>\n      </div>\n\n      <p style=\"font-size:11px;color:var(--dtext-soft);margin:10px 0 0;\">Investimento total (calculado): <b id=\"total-preview\">R$ 550,00</b></p>\n\n      <div class=\"toggle-row\" style=\"margin-top:16px;\">\n        <label for=\"chk-pagamento\">Incluir formas de pagamento</label>\n        <div class=\"switch\"><input type=\"checkbox\" id=\"chk-pagamento\" onchange=\"atualizarPagamento()\"><div class=\"track\"></div><div class=\"thumb\"></div></div>\n      </div>\n      <textarea id=\"in-pagamento\" rows=\"2\" placeholder=\"Ex: 50% na aprovação, 50% na entrega\" oninput=\"atualizarPagamento()\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>Observações</h2>\n      <label>Texto adicional (orientações, adendos etc. — aparece no final da proposta)</label>\n      <textarea id=\"in-observacoes\" rows=\"4\" placeholder=\"Ex: Valores válidos por 15 dias. Deslocamento fora da região metropolitana cobrado à parte.\" oninput=\"atualizarObservacoes()\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <details class=\"fixed\">\n        <summary>Dados fixos da fuzz (raramente mudam)</summary>\n        <label>Instagram</label>\n        <input type=\"text\" id=\"in-fx-insta\" value=\"@fuzz.midia\">\n        <label>Site</label>\n        <input type=\"text\" id=\"in-fx-site\" value=\"www.fuzzfilmes.com\">\n        <label>Telefone</label>\n        <input type=\"text\" id=\"in-fx-tel\" value=\"(55) 99147-8685\">\n        <label style=\"margin-top:14px;\">Corrigir contador de numeração (avançado)</label>\n        <input type=\"text\" id=\"in-corrige-contador\" placeholder=\"ex: 12\">\n        <button class=\"add-btn\" style=\"margin-top:6px;\" onclick=\"corrigirContador()\">Salvar contador</button>\n      </details>\n    </div>\n  </div>\n\n  <!-- ================= PREVIEW ================= -->\n  <div class=\"preview-wrap\">\n    <div class=\"sheet\" id=\"sheet\">\n      <div class=\"slate\">Nº <span id=\"pv-numero\">001</span></div>\n\n      <div class=\"head\">\n        <div>\n          <h1>PROPOSTA</h1>\n          <div class=\"titulo\" id=\"pv-titulo\">Produção de Podcast</div>\n          <div class=\"data\">DATA: <span id=\"pv-data\">09/07/2026</span></div>\n        </div>\n        <div class=\"logo\" id=\"pv-logo\"><img src=\"data:image/png;base64,\" alt=\"fuzz\"></div>\n      </div>\n\n      <div class=\"info-columns\" id=\"pv-info-columns\">\n        <div class=\"info-col\" id=\"pv-col-cliente\">\n          <span class=\"name\" id=\"pv-cli-nome\"></span>\n          <div class=\"info-line\" id=\"linha-cli-razao\"><b>Razão Social:</b> <span id=\"pv-cli-razao\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-endereco\"><b>Endereço:</b> <span id=\"pv-cli-endereco\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-bairro\"><b>Bairro:</b> <span id=\"pv-cli-bairro\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-municipio\"><b>Município:</b> <span id=\"pv-cli-municipio\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-estado\"><b>Estado:</b> <span id=\"pv-cli-estado\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-cep\"><b>CEP:</b> <span id=\"pv-cli-cep\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-telefone\"><b>Telefone:</b> <span id=\"pv-cli-telefone\"></span></div>\n          <div class=\"info-line\" id=\"linha-cli-cnpj\"><b>CNPJ:</b> <span id=\"pv-cli-cnpj\"></span></div>\n        </div>\n        <div class=\"info-divider\" id=\"pv-info-divider\"></div>\n        <div class=\"info-col\" id=\"pv-col-fuzz\">\n          <span class=\"name\" id=\"pv-fuzz-nome\">Fuzz Filmes</span>\n          <b>Razão Social:</b> <span id=\"pv-fuzz-razao\"></span><br>\n          <b>Endereço:</b> <span id=\"pv-fuzz-endereco\"></span><br>\n          <b>Telefone:</b> <span id=\"pv-fuzz-telefone\">(55) 99147-8685</span><br>\n          <b>CNPJ:</b> <span id=\"pv-fuzz-cnpj\"></span>\n        </div>\n      </div>\n\n      <div class=\"section\">\n        <h2>Produção</h2>\n        <ul id=\"pv-lista-producao\"></ul>\n      </div>\n\n      <div class=\"section\">\n        <h2>Entrega</h2>\n        <ul id=\"pv-lista-entrega\"></ul>\n      </div>\n\n      <hr class=\"rule\">\n\n      <div class=\"section\" id=\"pv-investimento-section\" style=\"display:none;\">\n        <h2>Investimento</h2>\n        <div id=\"pv-lista-investimento\"></div>\n      </div>\n\n      <div class=\"total\">\n        <div class=\"label\">*Investimento total</div>\n        <div class=\"value\">R$ <span id=\"pv-valor\">550,00</span></div>\n      </div>\n      <div class=\"pagamento hidden\" id=\"pv-pagamento-row\"><b>Formas de pagamento:</b> <span id=\"pv-pagamento\"></span></div>\n\n      <div class=\"section\" id=\"pv-observacoes-wrap\" style=\"display:none;\">\n        <h2>Observações</h2>\n        <p id=\"pv-observacoes\" style=\"font-size:12px;line-height:1.6;color:var(--ink-soft);white-space:pre-wrap;margin:0;\"></p>\n      </div>\n\n      <div class=\"footer\">\n        <span id=\"pv-fx-insta\">@fuzz.midia</span> | <span id=\"pv-fx-site\">www.fuzzfilmes.com</span> | <span id=\"pv-fx-tel\">(55) 99147-8685</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<button class=\"print-btn\" onclick=\"window.print()\">Baixar PDF / Imprimir</button>\n<button class=\"print-btn\" id=\"btn-salvar-painel\" style=\"bottom:78px;background:var(--dpanel-2);border-color:var(--dline);color:var(--dtext);box-shadow:none;\" onclick=\"enviarParaPainel()\">↳ Salvar cliente e proposta no Painel</button>\n\n<script>\nlet data = {\n  producao: [\n    \"Produção de 1 episódio de podcast\",\n    \"Captação de áudio com até 4 participantes simultâneos;\",\n    \"Captação de vídeo com 2 câmeras;\"\n  ],\n  entrega: [\n    \"Podcast editado em formato MP3;\",\n    \"Podcast editado em formato de vídeo MP4 e resolução FullHD (1920x1080);\",\n    \"Edição de 4 cortes por episódio para redes sociais;\",\n    \"Backup e armazenamento de arquivos pela plataforma GoogleDrive;\"\n  ]\n};\n\nconst simpleBindings = [\n  ['in-titulo','pv-titulo'],['in-data','pv-data'],\n  ['in-cli-nome','pv-cli-nome'],['in-cli-razao','pv-cli-razao'],['in-cli-endereco','pv-cli-endereco'],\n  ['in-cli-bairro','pv-cli-bairro'],['in-cli-municipio','pv-cli-municipio'],['in-cli-estado','pv-cli-estado'],\n  ['in-cli-cep','pv-cli-cep'],['in-cli-telefone','pv-cli-telefone'],['in-cli-cnpj','pv-cli-cnpj'],\n  ['in-fuzz-nome','pv-fuzz-nome'],['in-fuzz-razao','pv-fuzz-razao'],['in-fuzz-endereco','pv-fuzz-endereco'],\n  ['in-fuzz-telefone','pv-fuzz-telefone'],['in-fuzz-cnpj','pv-fuzz-cnpj'],\n  ['in-fx-insta','pv-fx-insta'],['in-fx-site','pv-fx-site'],['in-fx-tel','pv-fx-tel']\n];\n\nfunction bindSimple(){\n  simpleBindings.forEach(([inId,pvId])=>{\n    const inEl = document.getElementById(inId);\n    const pvEl = document.getElementById(pvId);\n    pvEl.textContent = inEl.value;\n    inEl.addEventListener('input', ()=> pvEl.textContent = inEl.value);\n  });\n}\n\nconst CLIENTE_DETALHE_CAMPOS = ['razao','endereco','bairro','municipio','estado','cep','telefone','cnpj'];\n\nfunction atualizarVisibilidadeClienteDetalhe(campo){\n  const pv = document.getElementById('pv-cli-' + campo);\n  const linha = document.getElementById('linha-cli-' + campo);\n  if (pv && linha) linha.style.display = pv.textContent.trim() ? '' : 'none';\n}\n\nfunction initVisibilidadeClienteDetalhes(){\n  CLIENTE_DETALHE_CAMPOS.forEach((campo)=>{\n    const inEl = document.getElementById('in-cli-' + campo);\n    if (!inEl) return;\n    inEl.addEventListener('input', ()=> atualizarVisibilidadeClienteDetalhe(campo));\n    atualizarVisibilidadeClienteDetalhe(campo);\n  });\n}\n\nlet listaClientes = [];\n\nfunction popularSelectClientes(){\n  const sel = document.getElementById('in-cliente-selecionar');\n  if (!sel) return;\n  sel.innerHTML = '<option value=\"\">— Selecionar —</option>';\n  listaClientes.forEach((c, idx)=>{\n    const opt = document.createElement('option');\n    opt.value = String(idx);\n    opt.textContent = c.nome || '(sem nome)';\n    sel.appendChild(opt);\n  });\n}\n\nfunction preencherClienteSelecionado(){\n  const sel = document.getElementById('in-cliente-selecionar');\n  const idx = sel.value;\n  if (idx === '') return;\n  const c = listaClientes[Number(idx)];\n  if (!c) return;\n  const mapa = {\n    'in-cli-nome': c.nome,\n    'in-cli-razao': c.razaoSocial,\n    'in-cli-endereco': c.endereco,\n    'in-cli-bairro': c.bairro,\n    'in-cli-municipio': c.municipio,\n    'in-cli-estado': c.estado,\n    'in-cli-cep': c.cep,\n    'in-cli-telefone': c.telefone,\n    'in-cli-cnpj': c.cnpj\n  };\n  Object.entries(mapa).forEach(([id, val])=>{\n    const el = document.getElementById(id);\n    if (!el) return;\n    el.value = val || '';\n    el.dispatchEvent(new Event('input'));\n  });\n}\n\nconst TIPO_PRODUCAO_TEMPLATES = {\n  'Podcast': {\n    producao: [\n      'Produção de 1 episódio de podcast;',\n      'Captação de áudio com até 4 participantes simultâneos;',\n      'Captação de vídeo com 2 câmeras;'\n    ],\n    entrega: [\n      'Podcast editado em formato MP3;',\n      'Podcast editado em formato de vídeo MP4 e resolução FullHD (1920x1080);',\n      'Edição de 4 cortes por episódio para redes sociais;',\n      'Envio da primeira versão em até 5 dias após gravação;',\n      'Backup e armazenamento de arquivos pela plataforma GoogleDrive;'\n    ]\n  },\n  'Institucional': {\n    producao: [\n      'Produção de 1 vídeo Institucional;',\n      'Captação com câmera 4k;',\n      'Captação de imagens aéreas com Drone;',\n      'Locução/Narração profissional;'\n    ],\n    entrega: [\n      'Roteiro completo (texto + sugestão de imagens/cenas) para aprovação do cliente;',\n      'Vídeo Editado em formato MP4 e resolução FullHD (1920x1080);',\n      'Envio e Backup de arquivos pela plataforma GoogleDrive;'\n    ]\n  },\n  'Produção de Conteúdo': {\n    producao: [\n      'Produção de 1 vídeo para Redes Sociais;',\n      'Captação com câmera 4k, estabilizador de imagem, iluminação profissional e teleprompter;',\n      'Auxílio na construção de roteiros;'\n    ],\n    entrega: [\n      'Vídeo Editado em formato MP4 e resolução FullHD (1080x1920);',\n      'Envio da primeira versão em até 5 dias após gravação;',\n      'Envio e Backup de arquivos pela plataforma GoogleDrive;'\n    ]\n  }\n};\n\nfunction aplicarTemplateTipoProducao(){\n  const tipo = document.getElementById('in-tipo-producao').value;\n  const modelo = TIPO_PRODUCAO_TEMPLATES[tipo];\n  if (!modelo) return;\n  data.producao = [...modelo.producao];\n  data.entrega = [...modelo.entrega];\n  renderList('producao');\n  renderList('entrega');\n}\n\nfunction moverItem(key, idx, direcao){\n  const novoIdx = idx + direcao;\n  if(novoIdx < 0 || novoIdx >= data[key].length) return;\n  const temp = data[key][idx];\n  data[key][idx] = data[key][novoIdx];\n  data[key][novoIdx] = temp;\n  renderList(key);\n}\n\nfunction renderList(key){\n  const editorHost = document.getElementById('lista-'+key);\n  const previewHost = document.getElementById('pv-lista-'+key);\n  editorHost.innerHTML = '';\n  previewHost.innerHTML = '';\n  data[key].forEach((val, idx)=>{\n    const row = document.createElement('div');\n    row.className = 'list-item';\n    const setas = document.createElement('div');\n    setas.style.display = 'flex';\n    setas.style.flexDirection = 'column';\n    const up = document.createElement('button');\n    up.textContent = '▲'; up.title = 'mover para cima';\n    up.style.fontSize = '9px'; up.style.padding = '0'; up.style.height = '15px'; up.style.width = '22px';\n    up.disabled = idx === 0;\n    up.onclick = ()=> moverItem(key, idx, -1);\n    const down = document.createElement('button');\n    down.textContent = '▼'; down.title = 'mover para baixo';\n    down.style.fontSize = '9px'; down.style.padding = '0'; down.style.height = '15px'; down.style.width = '22px';\n    down.disabled = idx === data[key].length - 1;\n    down.onclick = ()=> moverItem(key, idx, 1);\n    setas.appendChild(up); setas.appendChild(down);\n    const inp = document.createElement('input');\n    inp.type='text';\n    inp.value=val;\n    inp.addEventListener('input', ()=>{ data[key][idx]=inp.value; renderPreviewList(key); });\n    const del = document.createElement('button');\n    del.textContent='×';\n    del.title='remover';\n    del.onclick = ()=>{ data[key].splice(idx,1); renderList(key); };\n    row.appendChild(setas); row.appendChild(inp); row.appendChild(del);\n    editorHost.appendChild(row);\n  });\n  renderPreviewList(key);\n}\n\nfunction renderPreviewList(key){\n  const previewHost = document.getElementById('pv-lista-'+key);\n  previewHost.innerHTML = '';\n  data[key].forEach(val=>{\n    const li = document.createElement('li');\n    li.textContent = val;\n    previewHost.appendChild(li);\n  });\n}\n\nfunction addItem(key){\n  data[key].push('Novo item');\n  renderList(key);\n}\n\nfunction atualizarColunas(){\n  const cliOn = document.getElementById('chk-cliente').checked;\n  const fuzzOn = document.getElementById('chk-fuzzdados').checked;\n  const wrap = document.getElementById('pv-info-columns');\n  const colCli = document.getElementById('pv-col-cliente');\n  const colFuzz = document.getElementById('pv-col-fuzz');\n  const divider = document.getElementById('pv-info-divider');\n\n  colCli.classList.toggle('hidden', !cliOn);\n  colFuzz.classList.toggle('hidden', !fuzzOn);\n\n  if(cliOn && fuzzOn){\n    colCli.classList.remove('full'); colFuzz.classList.remove('full');\n    divider.classList.remove('hidden');\n    wrap.classList.remove('empty');\n  } else if(cliOn || fuzzOn){\n    colCli.classList.toggle('full', cliOn);\n    colFuzz.classList.toggle('full', fuzzOn);\n    divider.classList.add('hidden');\n    wrap.classList.remove('empty');\n  } else {\n    divider.classList.add('hidden');\n    wrap.classList.add('empty');\n  }\n}\n\nfunction parseBR(str){\n  if(!str) return 0;\n  let s = String(str).replace(/[^\\d,.-]/g,'');\n  if(s.indexOf(',') !== -1){\n    s = s.replace(/\\./g,'').replace(',', '.');\n  }\n  const n = parseFloat(s);\n  return isNaN(n) ? 0 : n;\n}\n\nfunction formatBR(n){\n  return n.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});\n}\n\nlet investimentoItens = [\n  {label:'Captação', valor:''},\n  {label:'Edição', valor:''},\n  {label:'Deslocamento', valor:''}\n];\n\nfunction renderInvestimentoList(){\n  const editorHost = document.getElementById('lista-investimento');\n  editorHost.innerHTML = '';\n  investimentoItens.forEach((item, idx)=>{\n    const row = document.createElement('div');\n    row.className = 'list-item';\n    const inpLabel = document.createElement('input');\n    inpLabel.type='text'; inpLabel.placeholder='Item (ex: Captação)'; inpLabel.value=item.label;\n    inpLabel.style.flex='2';\n    inpLabel.addEventListener('input', ()=>{ investimentoItens[idx].label=inpLabel.value; renderPreviewInvestimento(); });\n    const inpValor = document.createElement('input');\n    inpValor.type='text'; inpValor.placeholder='0,00'; inpValor.value=item.valor;\n    inpValor.style.flex='1';\n    inpValor.addEventListener('input', ()=>{ investimentoItens[idx].valor=inpValor.value; recalcularTotal(); });\n    const del = document.createElement('button');\n    del.textContent='×'; del.title='remover';\n    del.onclick = ()=>{ investimentoItens.splice(idx,1); renderInvestimentoList(); recalcularTotal(); };\n    row.appendChild(inpLabel); row.appendChild(inpValor); row.appendChild(del);\n    editorHost.appendChild(row);\n  });\n  renderPreviewInvestimento();\n}\n\nfunction renderPreviewInvestimento(){\n  const host = document.getElementById('pv-lista-investimento');\n  host.innerHTML = '';\n  investimentoItens.forEach(item=>{\n    const row = document.createElement('div');\n    row.className = 'valor-linha';\n    const l = document.createElement('span'); l.textContent = item.label || '—';\n    const v = document.createElement('span'); v.className = 'v'; v.textContent = 'R$ ' + formatBR(parseBR(item.valor));\n    row.appendChild(l); row.appendChild(v);\n    host.appendChild(row);\n  });\n}\n\nfunction addItemInvestimento(){\n  investimentoItens.push({label:'', valor:''});\n  renderInvestimentoList();\n}\n\nfunction atualizarModoValor(){\n  const detalhar = document.getElementById('chk-detalhar').checked;\n  document.getElementById('bloco-valor-simples').style.display = detalhar ? 'none' : 'block';\n  document.getElementById('bloco-valor-itens').style.display = detalhar ? 'block' : 'none';\n  document.getElementById('pv-investimento-section').style.display = detalhar ? 'block' : 'none';\n  recalcularTotal();\n}\n\nfunction recalcularTotal(){\n  const detalhar = document.getElementById('chk-detalhar').checked;\n  renderPreviewInvestimento();\n  let total = 0;\n  if(detalhar){\n    total = investimentoItens.reduce((sum, item)=> sum + parseBR(item.valor), 0);\n  } else {\n    total = parseBR(document.getElementById('in-valor').value);\n  }\n  const formatted = formatBR(total);\n  document.getElementById('pv-valor').textContent = formatted;\n  document.getElementById('total-preview').textContent = 'R$ ' + formatted;\n}\n\nfunction atualizarPagamento(){\n  const on = document.getElementById('chk-pagamento').checked;\n  const texto = document.getElementById('in-pagamento').value;\n  document.getElementById('pv-pagamento-row').classList.toggle('hidden', !on || !texto.trim());\n  document.getElementById('pv-pagamento').textContent = texto;\n}\n\nfunction atualizarObservacoes(){\n  const texto = document.getElementById('in-observacoes').value;\n  document.getElementById('pv-observacoes').textContent = texto;\n  document.getElementById('pv-observacoes-wrap').style.display = texto.trim() ? '' : 'none';\n}\n\nfunction getMesAno(dataStr){\n  const m = dataStr.match(/(\\d{1,2})\\/(\\d{1,2})\\/(\\d{2,4})/);\n  if(!m) return '';\n  const mes = m[2].padStart(2,'0');\n  const ano = m[3].length === 4 ? m[3].slice(-2) : m[3].padStart(2,'0');\n  return mes + '/' + ano;\n}\n\nfunction atualizarNumeroExibido(){\n  const inNumero = document.getElementById('in-numero');\n  const inData = document.getElementById('in-data');\n  const pvNumero = document.getElementById('pv-numero');\n  const mesAno = getMesAno(inData.value);\n  const nPad = inNumero.value.replace(/\\D/g,'').padStart(3,'0') || inNumero.value;\n  pvNumero.textContent = mesAno ? (nPad + '.' + mesAno) : nPad;\n}\n\nconst NUM_KEY = 'fuzzPropostaContador';\n\nfunction pad(n){ return String(n).padStart(3,'0'); }\n\nfunction ultimoNumeroSalvo(){\n  return parseInt(localStorage.getItem(NUM_KEY) || '0', 10);\n}\n\nfunction iniciarNumeracao(){\n  const proximo = ultimoNumeroSalvo() + 1;\n  const inNumero = document.getElementById('in-numero');\n  const inData = document.getElementById('in-data');\n  inNumero.value = pad(proximo);\n  atualizarNumeroExibido();\n  inNumero.addEventListener('input', atualizarNumeroExibido);\n  inData.addEventListener('input', atualizarNumeroExibido);\n}\n\nfunction aplicarProximoNumeroExterno(numeroStr){\n  const n = parseInt(String(numeroStr).replace(/\\D/g,''), 10);\n  if (isNaN(n)) return;\n  document.getElementById('in-numero').value = pad(n);\n  atualizarNumeroExibido();\n}\n\nwindow.addEventListener('message', (event)=>{\n  const msg = event.data;\n  if (!msg || typeof msg !== 'object' || msg.type !== 'fuzz:init-proposta') return;\n  const payload = msg.payload || {};\n  if (payload.proximoNumero) aplicarProximoNumeroExterno(payload.proximoNumero);\n  if (Array.isArray(payload.clientes)) {\n    listaClientes = payload.clientes;\n    popularSelectClientes();\n  }\n});\n\nfunction getValorTotalNumerico(){\n  const detalhar = document.getElementById('chk-detalhar').checked;\n  if(detalhar){\n    return investimentoItens.reduce((sum,item)=> sum + parseBR(item.valor), 0);\n  }\n  return parseBR(document.getElementById('in-valor').value);\n}\n\nfunction confirmarNumero(){\n  const inNumero = document.getElementById('in-numero');\n  const n = parseInt(inNumero.value.replace(/\\D/g,''), 10);\n  if(isNaN(n)){ alert('Digite um número válido antes de confirmar.'); return; }\n  localStorage.setItem(NUM_KEY, String(n));\n  alert('Número ' + pad(n) + ' reservado. Na próxima proposta, o campo já vai sugerir o número ' + pad(n+1) + '.');\n}\n\nfunction corrigirContador(){\n  const campo = document.getElementById('in-corrige-contador');\n  const n = parseInt(campo.value.replace(/\\D/g,''), 10);\n  if(isNaN(n)){ alert('Digite um número válido.'); return; }\n  localStorage.setItem(NUM_KEY, String(n));\n  campo.value = '';\n  alert('Contador ajustado para ' + pad(n) + '. Recarregue a página para ver o próximo número sugerido.');\n}\n\nfunction enviarParaPainel(){\n  const payload = {\n    numero: document.getElementById('pv-numero').textContent,\n    titulo: document.getElementById('in-titulo').value,\n    tipo: document.getElementById('in-tipo-producao').value,\n    data: document.getElementById('in-data').value,\n    cliente: {\n      nome: document.getElementById('in-cli-nome').value,\n      razaoSocial: document.getElementById('in-cli-razao').value,\n      endereco: document.getElementById('in-cli-endereco').value,\n      bairro: document.getElementById('in-cli-bairro').value,\n      municipio: document.getElementById('in-cli-municipio').value,\n      estado: document.getElementById('in-cli-estado').value,\n      cep: document.getElementById('in-cli-cep').value,\n      telefone: document.getElementById('in-cli-telefone').value,\n      cnpj: document.getElementById('in-cli-cnpj').value\n    },\n    valorTotal: getValorTotalNumerico()\n  };\n  if(!payload.cliente.nome.trim()){\n    alert('Preencha ao menos o nome do cliente antes de salvar no Painel.');\n    return;\n  }\n  window.parent.postMessage({ type: 'fuzz:proposta-concluida', payload: payload }, '*');\n  const btn = document.getElementById('btn-salvar-painel');\n  const original = btn.textContent;\n  btn.textContent = '✓ Enviado ao Painel';\n  setTimeout(()=>{ btn.textContent = original; }, 2200);\n}\n\nbindSimple();\nrenderList('producao');\nrenderList('entrega');\nrenderInvestimentoList();\niniciarNumeracao();\nfunction atualizarLogo(){\n  const on = document.getElementById('chk-logo').checked;\n  document.getElementById('pv-logo').style.display = on ? '' : 'none';\n}\n\natualizarColunas();\natualizarModoValor();\natualizarLogo();\ninitVisibilidadeClienteDetalhes();\nwindow.parent.postMessage({ type: 'fuzz:proposta-pronta' }, '*');\n</script>\n</body>\n</html>\n";

export const CALCULADORA_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Calculadora de Or\u00e7amento \u2014 fuzz</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js\"><\/script>\n<style>\n  :root{\n    --bg:#0A0B0D;\n    --panel:#131519;\n    --panel-2:#1B1E23;\n    --line:#262A30;\n    --text:#E8EAED;\n    --text-soft:#7D848C;\n    --accent:#FF3B30;\n    --accent-dim:rgba(255,59,48,.14);\n    --good:#34D399;\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:var(--bg);\n    font-family:'Space Grotesk',sans-serif;\n    color:var(--text);\n  }\n  .mono{font-family:'JetBrains Mono',monospace;font-variant-numeric:tabular-nums;}\n\n  .app{\n    display:grid;\n    grid-template-columns:420px 1fr;\n    min-height:100vh;\n  }\n\n  /* ---------------- CONTROLE (editor) ---------------- */\n  .editor{\n    background:var(--panel);\n    border-right:1px solid var(--line);\n    padding:30px 26px 60px;\n    overflow-y:auto;\n    max-height:100vh;\n  }\n  .editor .eyebrow{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10.5px;\n    letter-spacing:.18em;\n    color:var(--accent);\n    text-transform:uppercase;\n    margin:0 0 6px;\n  }\n  .editor h1{\n    font-size:20px;\n    font-weight:700;\n    margin:0 0 6px;\n    letter-spacing:-.01em;\n  }\n  .editor p.sub{\n    font-size:12px;\n    color:var(--text-soft);\n    margin:0 0 26px;\n    line-height:1.6;\n  }\n\n  .group{margin-bottom:24px;padding-bottom:20px;border-bottom:1px solid var(--line);}\n  .group:last-of-type{border-bottom:none;}\n  .group h2{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10.5px;\n    text-transform:uppercase;\n    letter-spacing:.14em;\n    color:var(--text-soft);\n    margin:0 0 12px;\n    display:flex;\n    align-items:center;\n    gap:8px;\n  }\n  .group h2:before{\n    content:'';\n    width:5px;height:5px;\n    border-radius:50%;\n    background:var(--line);\n  }\n\n  label{display:block;font-size:11px;color:var(--text-soft);margin:10px 0 5px;}\n  select, input[type=text], input[type=number]{\n    width:100%;\n    font-family:'JetBrains Mono',monospace;\n    font-size:13px;\n    padding:9px 10px;\n    border:1px solid var(--line);\n    border-radius:6px;\n    background:var(--panel-2);\n    color:var(--text);\n    transition:border-color .15s;\n  }\n  select{font-family:'Space Grotesk',sans-serif;}\n  input::placeholder{color:#4A4F56;font-family:'Space Grotesk',sans-serif;font-size:11.5px;}\n  select:focus, input:focus{outline:none;border-color:var(--accent);}\n\n  .row2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n\n  /* pill toggle switches */\n  .toggle-row{display:flex;align-items:center;gap:10px;margin:12px 0;}\n  .toggle-row label{margin:0;font-size:12px;color:var(--text);flex:1;cursor:default;}\n  .switch{\n    position:relative;\n    width:34px;height:19px;\n    flex:0 0 auto;\n    cursor:pointer;\n  }\n  .switch input{position:absolute;opacity:0;width:100%;height:100%;margin:0;cursor:pointer;z-index:2;}\n  .switch .track{\n    position:absolute;inset:0;\n    background:var(--panel-2);\n    border:1px solid var(--line);\n    border-radius:20px;\n    transition:.15s;\n  }\n  .switch .thumb{\n    position:absolute;top:2px;left:2px;\n    width:13px;height:13px;\n    border-radius:50%;\n    background:var(--text-soft);\n    transition:.15s;\n  }\n  .switch input:checked + .track{background:var(--accent-dim);border-color:var(--accent);}\n  .switch input:checked ~ .thumb{transform:translateX(15px);background:var(--accent);}\n\n  .toggle-row .mini-input{width:84px;flex:0 0 auto;margin-left:auto;}\n\n  .edicao-row{\n    border:1px solid var(--line);\n    border-radius:8px;\n    padding:12px;\n    margin-bottom:8px;\n    background:var(--panel-2);\n  }\n  .edicao-row .linha1{display:flex;gap:8px;align-items:center;margin-bottom:8px;}\n  .edicao-row select{flex:1;}\n  .edicao-row .remover{\n    background:none;border:1px solid var(--line);color:var(--text-soft);cursor:pointer;\n    font-size:14px;line-height:1;padding:0;width:26px;height:26px;border-radius:5px;flex:0 0 auto;\n  }\n  .edicao-row .remover:hover{border-color:var(--accent);color:var(--accent);}\n\n  .add-btn{\n    margin-top:4px;\n    padding:9px 12px;\n    font-size:11.5px;\n    font-weight:600;\n    letter-spacing:.03em;\n    border:1px dashed var(--line);\n    background:transparent;\n    color:var(--text-soft);\n    border-radius:6px;\n    cursor:pointer;\n    width:100%;\n    transition:.15s;\n  }\n  .add-btn:hover{border-color:var(--accent);color:var(--accent);}\n\n  .copy-btn{\n    margin-top:22px;\n    padding:13px;\n    width:100%;\n    font-size:12.5px;\n    font-weight:600;\n    letter-spacing:.03em;\n    font-family:'JetBrains Mono',monospace;\n    text-transform:uppercase;\n    border:1px solid var(--line);\n    background:var(--panel-2);\n    color:var(--text);\n    border-radius:7px;\n    cursor:pointer;\n    transition:.15s;\n  }\n  .copy-btn:hover{border-color:var(--accent);}\n\n  /* ---------------- MONITOR (resultado) ---------------- */\n  .result-wrap{padding:48px;display:flex;justify-content:center;align-items:flex-start;}\n  .result{\n    width:460px;\n    background:var(--panel);\n    border:1px solid var(--line);\n    border-radius:14px;\n    padding:30px 30px 26px;\n    position:relative;\n  }\n  /* viewfinder corner brackets \u2014 signature element */\n  .result:before, .result:after,\n  .result .br-tr, .result .br-bl{\n    content:'';\n    position:absolute;\n    width:16px;height:16px;\n    border:2px solid var(--line);\n  }\n  .result:before{ top:-1px; left:-1px; border-right:none; border-bottom:none; border-top-left-radius:6px;}\n  .result:after{ bottom:-1px; right:-1px; border-left:none; border-top:none; border-bottom-right-radius:6px;}\n  .result .br-tr{ top:-1px; right:-1px; border-left:none; border-bottom:none; border-top-right-radius:6px;}\n  .result .br-bl{ bottom:-1px; left:-1px; border-right:none; border-top:none; border-bottom-left-radius:6px;}\n\n  .monitor-head{\n    display:flex;\n    align-items:center;\n    gap:8px;\n    margin-bottom:4px;\n  }\n  .rec-dot{\n    width:7px;height:7px;\n    border-radius:50%;\n    background:var(--accent);\n    box-shadow:0 0 8px var(--accent);\n    animation:pulse 1.8s ease-in-out infinite;\n  }\n  @keyframes pulse{ 0%,100%{opacity:1;} 50%{opacity:.35;} }\n  .monitor-head .label{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10.5px;\n    letter-spacing:.18em;\n    color:var(--text-soft);\n    text-transform:uppercase;\n  }\n  .result h1{\n    font-size:22px;\n    font-weight:700;\n    margin:2px 0 2px;\n    letter-spacing:-.01em;\n  }\n  .result .tipo-atual{\n    font-family:'JetBrains Mono',monospace;\n    font-size:11.5px;\n    color:var(--text-soft);\n    margin-bottom:22px;\n  }\n\n  .linha{\n    display:flex;\n    justify-content:space-between;\n    gap:10px;\n    font-size:13px;\n    padding:10px 0;\n    border-top:1px solid var(--line);\n  }\n  .linha span:first-child{color:var(--text);}\n  .linha .v{white-space:nowrap;font-weight:600;font-family:'JetBrains Mono',monospace;}\n  .linha.acrescimo span:first-child{color:var(--text-soft);}\n  .linha.acrescimo .v{color:var(--text-soft);}\n\n  .subtotal{\n    display:flex;justify-content:space-between;align-items:baseline;\n    font-size:13px;font-weight:600;\n    padding:14px 0;\n    margin-top:4px;\n    border-top:1px solid var(--line);\n    color:var(--text-soft);\n  }\n  .subtotal .v{font-family:'JetBrains Mono',monospace;color:var(--text);font-weight:600;}\n\n  .total-final{\n    text-align:center;\n    padding:22px 16px;\n    margin-top:6px;\n    background:var(--accent-dim);\n    border:1px solid rgba(255,59,48,.3);\n    border-radius:10px;\n  }\n  .total-final .label{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--text-soft);\n  }\n  .total-final .value{\n    font-family:'JetBrains Mono',monospace;\n    font-weight:700;\n    font-size:36px;\n    margin-top:8px;\n    color:var(--text);\n    text-shadow:0 0 24px var(--accent-dim);\n  }\n\n  .info-linha{\n    text-align:center;\n    font-size:11.5px;\n    font-family:'JetBrains Mono',monospace;\n    color:var(--text-soft);\n    margin-top:10px;\n  }\n\n  .imposto-info{\n    margin-top:18px;\n    padding:14px 16px;\n    background:var(--panel-2);\n    border:1px solid var(--line);\n    border-radius:8px;\n    font-size:11.5px;\n    color:var(--text-soft);\n    line-height:1.7;\n  }\n  .imposto-info b{color:var(--text);}\n  .imposto-info .liquido{color:var(--good);font-weight:700;}\n\n  .export-row{display:flex;gap:8px;margin-top:18px;}\n  .export-btn{\n    flex:1;\n    padding:11px;\n    font-family:'JetBrains Mono',monospace;\n    font-size:11px;\n    font-weight:600;\n    letter-spacing:.04em;\n    text-transform:uppercase;\n    border:1px solid var(--line);\n    background:transparent;\n    color:var(--text-soft);\n    border-radius:7px;\n    cursor:pointer;\n    transition:.15s;\n  }\n  .export-btn:hover{border-color:var(--accent);color:var(--text);}\n\n  @media print{\n    body{background:#fff;}\n    .editor{display:none !important;}\n    .app{display:block;}\n    .result-wrap{padding:0;}\n    .result{width:auto;background:var(--panel);}\n    .export-row{display:none !important;}\n    *{-webkit-print-color-adjust:exact !important;print-color-adjust:exact !important;}\n  }\n\n  @media (max-width:920px){\n    .app{grid-template-columns:1fr;}\n    .editor{max-height:none;border-right:none;border-bottom:1px solid var(--line);}\n    .result-wrap{padding:20px;}\n    .result{width:100%;}\n  }\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <div class=\"editor\">\n    <div class=\"eyebrow\">FUZZ \u00b7 OR\u00c7AMENTO</div>\n    <h1>Calculadora</h1>\n    <p class=\"sub\">Preencha os campos \u2014 o monitor ao lado atualiza em tempo real. Exporte o resultado em PDF ou PNG ao final.</p>\n\n    <div class=\"group\">\n      <h2>Tipo de servi\u00e7o</h2>\n      <select id=\"in-tipo\" onchange=\"aoMudarTipo()\">\n        <option value=\"conteudo\">V\u00eddeo de conte\u00fado</option>\n        <option value=\"podcast\">Podcast</option>\n        <option value=\"institucional\">Institucional</option>\n        <option value=\"freelancer\">Freelancer</option>\n        <option value=\"transmissao\">Transmiss\u00e3o ao vivo</option>\n      </select>\n    </div>\n\n    <div class=\"group\">\n      <h2>Pacote</h2>\n      <label>Quantidade de epis\u00f3dios/v\u00eddeos</label>\n      <input type=\"number\" id=\"in-quantidade\" value=\"1\" min=\"1\" step=\"1\" oninput=\"calcular()\">\n      <div class=\"toggle-row\">\n        <label>Desconto progressivo por quantidade</label>\n        <div class=\"switch\">\n          <input type=\"checkbox\" id=\"chk-desconto-progressivo\" checked onchange=\"calcular()\">\n          <div class=\"track\"></div><div class=\"thumb\"></div>\n        </div>\n      </div>\n      <label>Desconto por unidade adicional (%)</label>\n      <input type=\"number\" id=\"in-desconto-progressivo\" value=\"35\" min=\"0\" max=\"90\" step=\"1\" oninput=\"calcular()\">\n      <p style=\"font-size:11px;color:var(--text-soft);margin:8px 0 0;line-height:1.6;\">Cada unidade al\u00e9m da 1\u00aa entra com esse desconto sobre a anterior. Ajuste at\u00e9 bater com sua tabela real.</p>\n      <label style=\"margin-top:14px;\">Valor final do pacote (opcional)</label>\n      <input type=\"number\" id=\"in-pacote-override\" placeholder=\"Deixe em branco pra usar o valor calculado\" min=\"0\" step=\"1\" oninput=\"calcular()\">\n      <p style=\"font-size:11px;color:var(--text-soft);margin:8px 0 0;line-height:1.6;\">Preencha se estiver usando sua tabela comercial de pacotes em vez do valor calculado por hora.</p>\n    </div>\n\n    <div class=\"group\">\n      <h2>Capta\u00e7\u00e3o</h2>\n      <div class=\"row2\">\n        <div>\n          <label>Horas de capta\u00e7\u00e3o</label>\n          <input type=\"number\" id=\"in-horas-captacao\" value=\"4\" min=\"0\" step=\"0.5\" oninput=\"calcular()\">\n        </div>\n        <div>\n          <label>Valor/hora (R$)</label>\n          <input type=\"number\" id=\"in-valor-captacao\" value=\"80\" min=\"0\" step=\"1\" oninput=\"calcular()\">\n        </div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Edi\u00e7\u00e3o</h2>\n      <div id=\"lista-edicao\"></div>\n      <button class=\"add-btn\" onclick=\"addEdicaoRow()\">+ adicionar linha de edi\u00e7\u00e3o</button>\n    </div>\n\n    <div class=\"group\">\n      <h2>Equipamentos</h2>\n      <div class=\"toggle-row\">\n        <label>Drone</label>\n        <input type=\"number\" id=\"in-drone\" class=\"mini-input\" value=\"300\" min=\"0\" oninput=\"calcular()\">\n        <div class=\"switch\">\n          <input type=\"checkbox\" id=\"chk-drone\" onchange=\"calcular()\">\n          <div class=\"track\"></div><div class=\"thumb\"></div>\n        </div>\n      </div>\n      <div class=\"toggle-row\">\n        <label>Equip. de transmiss\u00e3o</label>\n        <input type=\"number\" id=\"in-transmissao\" class=\"mini-input\" value=\"1200\" min=\"0\" oninput=\"calcular()\">\n        <div class=\"switch\">\n          <input type=\"checkbox\" id=\"chk-transmissao\" onchange=\"calcular()\">\n          <div class=\"track\"></div><div class=\"thumb\"></div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Deslocamento</h2>\n      <div class=\"toggle-row\">\n        <label>Incluir deslocamento</label>\n        <input type=\"number\" id=\"in-deslocamento\" class=\"mini-input\" value=\"0\" min=\"0\" oninput=\"calcular()\">\n        <div class=\"switch\">\n          <input type=\"checkbox\" id=\"chk-deslocamento\" onchange=\"calcular()\">\n          <div class=\"track\"></div><div class=\"thumb\"></div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"group\">\n      <h2>Freelancers contratados</h2>\n      <div id=\"lista-freelancers\"></div>\n      <button class=\"add-btn\" onclick=\"addFreelancerRow()\">+ adicionar freelancer</button>\n    </div>\n\n    <div class=\"group\">\n      <h2>Imposto</h2>\n      <div class=\"row2\">\n        <div>\n          <label>Al\u00edquota (%)</label>\n          <input type=\"number\" id=\"in-imposto\" value=\"6\" min=\"0\" step=\"0.5\" oninput=\"calcular()\">\n        </div>\n        <div>\n          <label>Aplica\u00e7\u00e3o</label>\n          <select id=\"in-imposto-modo\" onchange=\"calcular()\">\n            <option value=\"informativo\">S\u00f3 informativo</option>\n            <option value=\"somar\">Somar ao valor do cliente</option>\n          </select>\n        </div>\n      </div>\n      <p id=\"nota-imposto-override\" style=\"font-size:11px;color:var(--text-soft);margin:8px 0 0;display:none;line-height:1.6;\">Com o \"Valor final do pacote\" preenchido, o imposto sempre fica informativo \u2014 o pacote j\u00e1 \u00e9 o pre\u00e7o final.</p>\n    </div>\n\n    <button class=\"copy-btn\" onclick=\"copiarResumo()\">Copiar resumo</button>\n  </div>\n\n  <div class=\"result-wrap\">\n    <div class=\"result\" id=\"result-card\">\n      <div class=\"br-tr\"></div><div class=\"br-bl\"></div>\n      <div class=\"monitor-head\"><span class=\"rec-dot\"></span><span class=\"label\">Or\u00e7amento ao vivo</span></div>\n      <h1>Resultado</h1>\n      <div class=\"tipo-atual\" id=\"pv-tipo\">V\u00eddeo de conte\u00fado</div>\n\n      <div id=\"pv-linhas\"></div>\n\n      <div class=\"subtotal\">\n        <span>Subtotal</span>\n        <span class=\"v\" id=\"pv-subtotal\">R$ 0,00</span>\n      </div>\n\n      <div class=\"total-final\">\n        <div class=\"label\">Valor a cobrar do cliente</div>\n        <div class=\"value\" id=\"pv-total\">R$ 0,00</div>\n      </div>\n      <div class=\"info-linha\" id=\"pv-por-episodio\"></div>\n      <div class=\"info-linha\" id=\"pv-comparativo-pacote\"></div>\n\n      <div class=\"imposto-info\" id=\"pv-imposto-info\"></div>\n\n      <div class=\"export-row\">\n        <button class=\"export-btn\" onclick=\"exportarPDF()\">Exportar PDF</button>\n        <button class=\"export-btn\" onclick=\"exportarPNG()\">Exportar PNG</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nconst VALORES_TIPO = {\n  conteudo:      { captacao: 80,  label: 'V\u00eddeo de conte\u00fado' },\n  podcast:       { captacao: 100, label: 'Podcast' },\n  institucional: { captacao: 100, label: 'Institucional' },\n  freelancer:    { captacao: 100, label: 'Freelancer' },\n  transmissao:   { captacao: 80,  label: 'Transmiss\u00e3o ao vivo' }\n};\n\nlet edicaoItens = [{ tipo: 'interna', horas: 2, videos: 1 }];\nlet freelancerItens = [];\n\nfunction renderFreelancerList(){\n  const host = document.getElementById('lista-freelancers');\n  host.innerHTML = '';\n  freelancerItens.forEach((item, idx)=>{\n    const row = document.createElement('div');\n    row.className = 'edicao-row';\n\n    const linha1 = document.createElement('div');\n    linha1.className = 'linha1';\n    const inpFuncao = document.createElement('input');\n    inpFuncao.type = 'text'; inpFuncao.placeholder = 'Fun\u00e7\u00e3o (ex: operador de drone)';\n    inpFuncao.value = item.funcao;\n    inpFuncao.style.flex = '1';\n    inpFuncao.oninput = ()=>{ item.funcao = inpFuncao.value; calcular(); };\n    const rm = document.createElement('button');\n    rm.className = 'remover'; rm.textContent = '\u00d7'; rm.title = 'remover';\n    rm.onclick = ()=>{ freelancerItens.splice(idx,1); renderFreelancerList(); calcular(); };\n    linha1.appendChild(inpFuncao); linha1.appendChild(rm);\n    row.appendChild(linha1);\n\n    const lbl = document.createElement('label');\n    lbl.textContent = 'Valor (R$)'; lbl.style.margin = '0 0 3px';\n    const inpValor = document.createElement('input');\n    inpValor.type = 'number'; inpValor.min = '0'; inpValor.step = '1';\n    inpValor.value = item.valor;\n    inpValor.oninput = ()=>{ item.valor = parseFloat(inpValor.value)||0; calcular(); };\n    row.appendChild(lbl); row.appendChild(inpValor);\n\n    host.appendChild(row);\n  });\n}\n\nfunction addFreelancerRow(){\n  freelancerItens.push({ funcao: '', valor: 0 });\n  renderFreelancerList();\n  calcular();\n}\n\nfunction formatBR(n){\n  return n.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});\n}\n\nfunction aoMudarTipo(){\n  const tipo = document.getElementById('in-tipo').value;\n  const cfg = VALORES_TIPO[tipo];\n  document.getElementById('in-valor-captacao').value = cfg.captacao;\n  calcular();\n}\n\nfunction renderEdicaoList(){\n  const host = document.getElementById('lista-edicao');\n  host.innerHTML = '';\n  edicaoItens.forEach((item, idx)=>{\n    const row = document.createElement('div');\n    row.className = 'edicao-row';\n\n    const linha1 = document.createElement('div');\n    linha1.className = 'linha1';\n    const sel = document.createElement('select');\n    sel.innerHTML = '<option value=\"interna\">Interna (por hora)</option><option value=\"terceirizada\">Terceirizada (por v\u00eddeo)</option>';\n    sel.value = item.tipo;\n    sel.onchange = ()=>{ item.tipo = sel.value; renderEdicaoList(); };\n    const rm = document.createElement('button');\n    rm.className = 'remover'; rm.textContent = '\u00d7'; rm.title = 'remover';\n    rm.onclick = ()=>{ edicaoItens.splice(idx,1); renderEdicaoList(); calcular(); };\n    linha1.appendChild(sel); linha1.appendChild(rm);\n    row.appendChild(linha1);\n\n    if(item.tipo === 'interna'){\n      const lbl = document.createElement('label');\n      lbl.textContent = 'Horas de edi\u00e7\u00e3o'; lbl.style.margin = '0 0 3px';\n      const inp = document.createElement('input');\n      inp.type = 'number'; inp.min = '0'; inp.step = '0.5';\n      inp.value = item.horas;\n      inp.oninput = ()=>{ item.horas = parseFloat(inp.value)||0; calcular(); };\n      row.appendChild(lbl); row.appendChild(inp);\n    } else {\n      const lbl = document.createElement('label');\n      lbl.textContent = 'Quantidade de v\u00eddeos (R$90 cada)'; lbl.style.margin = '0 0 3px';\n      const inp = document.createElement('input');\n      inp.type = 'number'; inp.min = '0'; inp.step = '1';\n      inp.value = item.videos;\n      inp.oninput = ()=>{ item.videos = parseFloat(inp.value)||0; calcular(); };\n      row.appendChild(lbl); row.appendChild(inp);\n    }\n\n    host.appendChild(row);\n  });\n}\n\nfunction addEdicaoRow(){\n  edicaoItens.push({ tipo: 'interna', horas: 1, videos: 1 });\n  renderEdicaoList();\n  calcular();\n}\n\nfunction calcular(){\n  const tipo = document.getElementById('in-tipo').value;\n  const cfg = VALORES_TIPO[tipo];\n  document.getElementById('pv-tipo').textContent = cfg.label;\n\n  const horasCaptacao = parseFloat(document.getElementById('in-horas-captacao').value) || 0;\n  const valorCaptacaoHora = parseFloat(document.getElementById('in-valor-captacao').value) || 0;\n  const totalCaptacao = horasCaptacao * valorCaptacaoHora;\n\n  let totalEdicao = 0;\n  const linhasEdicao = [];\n  edicaoItens.forEach(item=>{\n    if(item.tipo === 'interna'){\n      const v = (item.horas||0) * 80;\n      totalEdicao += v;\n      if(item.horas) linhasEdicao.push({ label: 'Edi\u00e7\u00e3o interna (' + item.horas + 'h)', valor: v });\n    } else {\n      const v = (item.videos||0) * 90;\n      totalEdicao += v;\n      if(item.videos) linhasEdicao.push({ label: 'Edi\u00e7\u00e3o terceirizada (' + item.videos + ' v\u00eddeo(s))', valor: v });\n    }\n  });\n\n  const droneOn = document.getElementById('chk-drone').checked;\n  const droneValor = parseFloat(document.getElementById('in-drone').value) || 0;\n  const transmissaoOn = document.getElementById('chk-transmissao').checked;\n  const transmissaoValor = parseFloat(document.getElementById('in-transmissao').value) || 0;\n  const deslocamentoOn = document.getElementById('chk-deslocamento').checked;\n  const deslocamentoValor = parseFloat(document.getElementById('in-deslocamento').value) || 0;\n\n  const totalFreelancers = freelancerItens.reduce((sum, item)=> sum + (item.valor||0), 0);\n\n  let subtotalUnidade = totalCaptacao + totalEdicao + totalFreelancers;\n  if(droneOn) subtotalUnidade += droneValor;\n  if(transmissaoOn) subtotalUnidade += transmissaoValor;\n  if(deslocamentoOn) subtotalUnidade += deslocamentoValor;\n\n  const quantidade = Math.max(1, parseInt(document.getElementById('in-quantidade').value) || 1);\n  const descontoOn = document.getElementById('chk-desconto-progressivo').checked;\n  const descontoPct = parseFloat(document.getElementById('in-desconto-progressivo').value) || 0;\n\n  let subtotal = subtotalUnidade;\n  let multiplicador = quantidade;\n  if(quantidade > 1 && descontoOn){\n    const r = 1 - (descontoPct/100);\n    multiplicador = Math.abs(1-r) < 0.0001 ? quantidade : (1 - Math.pow(r, quantidade)) / (1-r);\n    subtotal = subtotalUnidade * multiplicador;\n  } else if(quantidade > 1){\n    subtotal = subtotalUnidade * quantidade;\n  }\n\n  const totalCliente = subtotal;\n\n  const impostoPct = parseFloat(document.getElementById('in-imposto').value) || 0;\n  const impostoModo = document.getElementById('in-imposto-modo').value;\n\n  let valorFinalCliente = totalCliente;\n  let valorImposto, valorLiquido;\n\n  if(impostoModo === 'somar'){\n    valorImposto = totalCliente * (impostoPct/100);\n    valorFinalCliente = totalCliente + valorImposto;\n    valorLiquido = totalCliente;\n  } else {\n    valorImposto = totalCliente * (impostoPct/100);\n    valorLiquido = totalCliente - valorImposto;\n  }\n\n  // Render linhas\n  const host = document.getElementById('pv-linhas');\n  host.innerHTML = '';\n  const addLinha = (label, valor, classe)=>{\n    const div = document.createElement('div');\n    div.className = 'linha' + (classe ? ' '+classe : '');\n    div.innerHTML = '<span>'+label+'</span><span class=\"v\">R$ '+formatBR(valor)+'</span>';\n    host.appendChild(div);\n  };\n  if(horasCaptacao) addLinha('Capta\u00e7\u00e3o (' + horasCaptacao + 'h)', totalCaptacao);\n  linhasEdicao.forEach(l=> addLinha(l.label, l.valor));\n  if(droneOn) addLinha('Drone', droneValor);\n  if(transmissaoOn) addLinha('Equip. de transmiss\u00e3o', transmissaoValor);\n  if(deslocamentoOn && deslocamentoValor) addLinha('Deslocamento', deslocamentoValor);\n  freelancerItens.forEach(item=>{\n    if(item.valor) addLinha('Freelancer' + (item.funcao ? ' \u2014 ' + item.funcao : ''), item.valor);\n  });\n  if(quantidade > 1){\n    const div = document.createElement('div');\n    div.className = 'linha acrescimo';\n    const textoDesconto = descontoOn ? ' (desconto progressivo)' : '';\n    div.innerHTML = '<span>\u00d7 ' + quantidade + ' unidades' + textoDesconto + '</span><span class=\"v\">R$ ' + formatBR(subtotalUnidade) + ' \u2192 R$ ' + formatBR(subtotal) + '</span>';\n    host.appendChild(div);\n  }\n\n  const overrideRaw = document.getElementById('in-pacote-override').value;\n  const temOverride = overrideRaw !== '' && !isNaN(parseFloat(overrideRaw));\n  const valorPacote = temOverride ? parseFloat(overrideRaw) : null;\n  const valorExibido = temOverride ? valorPacote : valorFinalCliente;\n\n  document.getElementById('pv-por-episodio').textContent =\n    quantidade > 1 ? (quantidade + ' UNIDADES \u2014 R$ ' + formatBR(valorExibido / quantidade) + ' / UN') : '';\n\n  const compHost = document.getElementById('pv-comparativo-pacote');\n  if(temOverride){\n    const diff = valorPacote - valorFinalCliente;\n    const sinal = diff >= 0 ? '+' : '';\n    compHost.textContent = 'CUSTO CALC.: R$ ' + formatBR(valorFinalCliente) + ' (' + sinal + formatBR(diff) + ')';\n  } else {\n    compHost.textContent = '';\n  }\n\n  document.getElementById('pv-subtotal').textContent = 'R$ ' + formatBR(subtotal);\n  document.getElementById('pv-total').textContent = 'R$ ' + formatBR(valorExibido);\n\n  const infoHost = document.getElementById('pv-imposto-info');\n  document.getElementById('nota-imposto-override').style.display = temOverride ? 'block' : 'none';\n  const modoEfetivo = temOverride ? 'informativo' : impostoModo;\n  const baseImposto = temOverride ? valorPacote : totalCliente;\n  const valorImpostoExibido = baseImposto * (impostoPct/100);\n  const valorLiquidoExibido = modoEfetivo === 'somar' ? baseImposto : baseImposto - valorImpostoExibido;\n  if(temOverride && impostoModo === 'somar'){\n    infoHost.innerHTML = 'Imposto de ' + impostoPct + '% sobre a nota: <b>R$ ' + formatBR(valorImpostoExibido) + '</b> \u2014 n\u00e3o somado, porque o valor do pacote j\u00e1 \u00e9 o pre\u00e7o final que voc\u00ea definiu.<br>Valor l\u00edquido estimado ap\u00f3s imposto: <span class=\"liquido\">R$ ' + formatBR(valorLiquidoExibido) + '</span>';\n  } else if(modoEfetivo === 'somar'){\n    infoHost.innerHTML = 'Imposto de ' + impostoPct + '% (R$ ' + formatBR(valorImpostoExibido) + ') <b>somado</b> ao valor do cliente.<br>Valor que fica pra fuzz antes do imposto: <span class=\"liquido\">R$ ' + formatBR(valorLiquidoExibido) + '</span>';\n  } else {\n    infoHost.innerHTML = 'Imposto de ' + impostoPct + '% sobre a nota: <b>R$ ' + formatBR(valorImpostoExibido) + '</b> (n\u00e3o somado ao valor do cliente \u2014 sai do seu faturamento).<br>Valor l\u00edquido estimado ap\u00f3s imposto: <span class=\"liquido\">R$ ' + formatBR(valorLiquidoExibido) + '</span>';\n  }\n}\n\nfunction copiarResumo(){\n  const tipo = document.getElementById('pv-tipo').textContent;\n  const total = document.getElementById('pv-total').textContent;\n  const linhas = Array.from(document.querySelectorAll('#pv-linhas .linha')).map(l=>{\n    const spans = l.querySelectorAll('span');\n    return '- ' + spans[0].textContent + ': ' + spans[1].textContent;\n  }).join('\\n');\n  const texto = 'Or\u00e7amento \u2014 ' + tipo + '\\n' + linhas + '\\n\\nValor total: ' + total;\n  navigator.clipboard.writeText(texto).then(()=>{\n    alert('Resumo copiado! J\u00e1 pode colar no gerador de propostas.');\n  }).catch(()=>{\n    alert('N\u00e3o consegui copiar automaticamente. Aqui est\u00e1 o resumo:\\n\\n' + texto);\n  });\n}\n\nfunction exportarPDF(){\n  window.print();\n}\n\nfunction exportarPNG(){\n  const card = document.getElementById('result-card');\n  html2canvas(card, {\n    backgroundColor: '#131519',\n    scale: 2,\n    ignoreElements: (el)=> el.classList && el.classList.contains('export-row')\n  }).then(canvas=>{\n    const link = document.createElement('a');\n    link.download = 'orcamento-fuzz.png';\n    link.href = canvas.toDataURL('image/png');\n    link.click();\n  }).catch(()=>{\n    alert('N\u00e3o consegui gerar o PNG agora. Tente novamente ou use o Exportar PDF.');\n  });\n}\n\nrenderEdicaoList();\nrenderFreelancerList();\ncalcular();\n<\/script>\n</body>\n</html>\n";

export const CONTRATO_HTML = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Gerador de Contrato</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo+Black&family=Space+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --paper:#F5F1E6;\n    --paper-dark:#EDE7D8;\n    --ink:#17140F;\n    --ink-soft:#5B5646;\n    --line:#CBC1A6;\n    --panel:#FFFDF8;\n\n    --bg:#0A0B0D;\n    --dpanel:#131519;\n    --dpanel-2:#1B1E23;\n    --dline:#262A30;\n    --dtext:#E8EAED;\n    --dtext-soft:#7D848C;\n    --accent:#FF3B30;\n    --accent-dim:rgba(255,59,48,.14);\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:var(--bg);\n    font-family:'Space Grotesk',sans-serif;\n    color:var(--dtext);\n  }\n  .app{\n    display:grid;\n    grid-template-columns:380px 1fr;\n    min-height:100vh;\n  }\n  .editor{\n    background:var(--dpanel);\n    padding:28px 26px 100px;\n    border-right:1px solid var(--dline);\n    overflow-y:auto;\n    max-height:100vh;\n  }\n  .editor h1{\n    font-size:19px;\n    font-weight:700;\n    letter-spacing:-.01em;\n    margin:0 0 4px;\n  }\n  .editor p.sub{\n    margin:0 0 24px;\n    font-size:12px;\n    color:var(--dtext-soft);\n    line-height:1.6;\n  }\n  .group{margin-bottom:22px;}\n  .group h2{\n    font-family:'JetBrains Mono',monospace;\n    font-size:10.5px;\n    text-transform:uppercase;\n    letter-spacing:.14em;\n    color:var(--dtext-soft);\n    margin:0 0 10px;\n    padding-bottom:8px;\n    border-bottom:1px solid var(--dline);\n  }\n  label{\n    display:block;\n    font-size:11.5px;\n    color:var(--dtext-soft);\n    margin:10px 0 5px;\n  }\n  input[type=text],input:not([type]),select,textarea{\n    width:100%;\n    font-family:inherit;\n    font-size:13px;\n    padding:8px 10px;\n    border:1px solid var(--dline);\n    border-radius:6px;\n    background:var(--dpanel-2);\n    color:var(--dtext);\n  }\n  textarea{\n    resize:vertical;\n    line-height:1.5;\n    font-size:12.5px;\n  }\n  input:focus,select:focus,textarea:focus{\n    outline:none;\n    border-color:var(--accent);\n  }\n  .row2{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n  .add-btn{\n    background:none;\n    border:1px dashed var(--dline);\n    color:var(--dtext-soft);\n    font-size:12px;\n    padding:8px 12px;\n    border-radius:6px;\n    cursor:pointer;\n    width:100%;\n    margin-top:6px;\n    font-family:inherit;\n  }\n  .add-btn:hover{border-color:var(--accent);color:var(--dtext);}\n  .hint{font-size:11px;color:var(--dtext-soft);margin:6px 0 0;line-height:1.5;}\n\n  /* ---------- PREVIEW / PAPER ---------- */\n  .preview-wrap{\n    padding:40px;\n    display:flex;\n    justify-content:center;\n    align-items:flex-start;\n  }\n  .sheet{\n    width:760px;\n    background:var(--paper);\n    background-image:radial-gradient(circle at 1px 1px, rgba(0,0,0,.035) 1px, transparent 0);\n    background-size:14px 14px;\n    padding:56px 60px 70px;\n    box-shadow:0 20px 50px rgba(0,0,0,.28);\n    color:var(--ink);\n  }\n  .sheet h1.doc-title{\n    font-family:'Archivo Black',sans-serif;\n    font-size:22px;\n    text-align:center;\n    letter-spacing:.02em;\n    margin:0 0 26px;\n  }\n  .sheet p{\n    font-size:12.5px;\n    line-height:1.7;\n    margin:0 0 14px;\n    text-align:justify;\n  }\n  .sheet .clausula{margin-bottom:20px;}\n  .sheet .clausula h2{\n    font-family:'Archivo Black',sans-serif;\n    font-size:13.5px;\n    margin:0 0 8px;\n  }\n  .sheet .clausula .corpo{\n    font-size:12.5px;\n    line-height:1.7;\n    white-space:pre-wrap;\n    text-align:justify;\n  }\n  .assinatura{\n    margin-top:44px;\n    text-align:center;\n  }\n  .assinatura .local-data{\n    text-align:center;\n    font-size:12.5px;\n    margin-bottom:44px;\n  }\n  .assinatura .linha{\n    display:flex;\n    justify-content:space-around;\n    gap:30px;\n    flex-wrap:wrap;\n  }\n  .assinatura .bloco{\n    min-width:220px;\n    text-align:center;\n  }\n  .assinatura .bloco .traco{\n    border-top:1px solid var(--ink);\n    margin-bottom:6px;\n    padding-top:6px;\n  }\n  .assinatura .bloco b{display:block;font-size:12px;}\n  .assinatura .bloco span{display:block;font-size:11px;color:var(--ink-soft);}\n\n  .print-btn{\n    position:fixed;\n    bottom:22px;\n    right:40px;\n    background:var(--accent);\n    color:#fff;\n    border:none;\n    padding:12px 20px;\n    border-radius:8px;\n    font-family:'Space Grotesk',sans-serif;\n    font-weight:600;\n    font-size:13px;\n    cursor:pointer;\n    box-shadow:0 10px 26px rgba(255,59,48,.35);\n    z-index:10;\n  }\n  .print-btn:hover{filter:brightness(1.08);}\n\n  @media print{\n    @page{ size:A4; margin:18mm 16mm; }\n    *{\n      -webkit-print-color-adjust: exact !important;\n      print-color-adjust: exact !important;\n      color-adjust: exact !important;\n    }\n    body{background:#fff;}\n    .editor,.print-btn{display:none !important;}\n    .app{display:block;}\n    .preview-wrap{padding:0;display:block;}\n    .sheet{box-shadow:none;width:auto;margin:0;padding:0;background:#fff !important;background-image:none !important;}\n  }\n  @media (max-width:860px){\n    .app{grid-template-columns:1fr;}\n    .editor{max-height:none;border-right:none;border-bottom:1px solid var(--dline);}\n    .print-btn{position:static;width:100%;margin-top:16px;}\n    .sheet{width:100%;padding:36px 24px;}\n  }\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <!-- ================= EDITOR ================= -->\n  <div class=\"editor\">\n    <h1>Gerador de Contrato</h1>\n    <p class=\"sub\">Escolha o tipo de contrato, o cliente, e ajuste as cláusulas se precisar. A prévia ao lado se atualiza sozinha.</p>\n\n    <div class=\"group\">\n      <h2>Tipo de contrato</h2>\n      <select id=\"in-tipo-contrato\" onchange=\"aplicarTemplateTipo()\">\n        <option value=\"podcast\">Podcast</option>\n        <option value=\"recorrente\">Conteúdo Recorrente</option>\n        <option value=\"institucional\">Institucional</option>\n      </select>\n    </div>\n\n    <div class=\"group\">\n      <h2>Contratante</h2>\n      <label>Selecionar cliente do painel (opcional)</label>\n      <select id=\"in-cliente-selecionar\" onchange=\"preencherClienteSelecionado()\">\n        <option value=\"\">— Selecionar —</option>\n      </select>\n      <label>Nome / Razão social (para a assinatura)</label>\n      <input type=\"text\" id=\"in-contratante-nome\" oninput=\"atualizarAssinatura()\">\n      <label>CPF ou CNPJ (para a assinatura)</label>\n      <input type=\"text\" id=\"in-contratante-doc\" oninput=\"atualizarAssinatura()\">\n      <label>Parágrafo de qualificação do contratante</label>\n      <textarea id=\"in-contratante-paragrafo\" rows=\"5\" oninput=\"atualizarClausula('contratante')\"></textarea>\n      <p class=\"hint\">Ao selecionar um cliente, esse texto é gerado automaticamente (CPF/pessoa física ou CNPJ/pessoa jurídica, conforme os dados). Pode ajustar livremente.</p>\n    </div>\n\n    <div class=\"group\">\n      <h2>I. Do objeto</h2>\n      <textarea id=\"in-objeto\" rows=\"3\" oninput=\"atualizarClausula('objeto')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>II. Da prestação dos serviços</h2>\n      <textarea id=\"in-prestacao\" rows=\"12\" oninput=\"atualizarClausula('prestacao')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>III. Do prazo</h2>\n      <textarea id=\"in-prazo\" rows=\"4\" oninput=\"atualizarClausula('prazo')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>IV. Da remuneração</h2>\n      <label>Valor (R$)</label>\n      <input type=\"text\" id=\"in-valor\" placeholder=\"Ex: 1.500,00\" oninput=\"atualizarValor()\">\n      <label style=\"margin-top:12px;\">Texto da cláusula (use {{VALOR}} onde o valor deve aparecer)</label>\n      <textarea id=\"in-remuneracao\" rows=\"7\" oninput=\"atualizarClausula('remuneracao')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>V. Das obrigações da contratada</h2>\n      <textarea id=\"in-obrig-contratada\" rows=\"8\" oninput=\"atualizarClausula('obrigContratada')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>VI. Das obrigações da contratante</h2>\n      <textarea id=\"in-obrig-contratante\" rows=\"5\" oninput=\"atualizarClausula('obrigContratante')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>VII. Da rescisão</h2>\n      <textarea id=\"in-rescisao\" rows=\"9\" oninput=\"atualizarClausula('rescisao')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>VIII. Dos direitos autorais</h2>\n      <textarea id=\"in-direitos\" rows=\"8\" oninput=\"atualizarClausula('direitos')\"></textarea>\n    </div>\n\n    <div class=\"group\">\n      <h2>Assinatura</h2>\n      <div class=\"row2\">\n        <div>\n          <label>Cidade</label>\n          <input type=\"text\" id=\"in-cidade\" value=\"Ijuí/RS\" oninput=\"atualizarAssinatura()\">\n        </div>\n        <div>\n          <label>Data</label>\n          <input type=\"text\" id=\"in-data-assinatura\" oninput=\"atualizarAssinatura()\">\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- ================= PREVIEW ================= -->\n  <div class=\"preview-wrap\">\n    <div class=\"sheet\" id=\"sheet\">\n      <h1 class=\"doc-title\">CONTRATO DE PRESTAÇÃO DE SERVIÇOS</h1>\n\n      <p><b>CONTRATANTE:</b> <span id=\"pv-contratante-paragrafo\"></span></p>\n\n      <p><b>CONTRATADA:</b> Vitor Henrique Mohr 03309589099, nome fantasia Fuzz Produtora de Vídeos, inscrita sob o CNPJ nº 33.811.775/0001-04, sediada na Rua Goiás, nº 369, Apto. 1005, Bairro Assis Brasil, no Município de Ijuí/RS, por seu representante legal, doravante designada CONTRATADA.</p>\n\n      <p>As partes acima nomeadas e qualificadas têm entre si certas e ajustadas o presente Contrato de Prestação de Serviços, que se regerá de acordo com as cláusulas e condições a seguir:</p>\n\n      <div class=\"clausula\">\n        <h2>I. Do Objeto</h2>\n        <div class=\"corpo\" id=\"pv-objeto\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>II. Da Prestação dos Serviços</h2>\n        <div class=\"corpo\" id=\"pv-prestacao\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>III. Do Prazo</h2>\n        <div class=\"corpo\" id=\"pv-prazo\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>IV. Da Remuneração dos Serviços</h2>\n        <div class=\"corpo\" id=\"pv-remuneracao\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>V. Das Obrigações da Contratada</h2>\n        <div class=\"corpo\" id=\"pv-obrig-contratada\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>VI. Das Obrigações da Contratante</h2>\n        <div class=\"corpo\" id=\"pv-obrig-contratante\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>VII. Da Rescisão</h2>\n        <div class=\"corpo\" id=\"pv-rescisao\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>VIII. Dos Direitos Autorais</h2>\n        <div class=\"corpo\" id=\"pv-direitos\"></div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>IX. Dos Casos Fortuitos</h2>\n        <div class=\"corpo\">9.1. Os casos fortuitos e de força maior serão excludentes de responsabilidade de ambas as partes, conforme disposto no artigo 393 e parágrafo único, do Código Civil.\n\n9.2. A Parte que for afetada por caso fortuito ou força maior, devidamente comprovados, deverá notificar a outra, de imediato, da extensão do fato e do prazo estimado durante o qual estará inabilitada a cumprir ou pelo qual será obrigada a atrasar o cumprimento de suas obrigações decorrentes deste Contrato.\n\n9.3. Cessados os efeitos de caso fortuito ou de força maior, a Parte afetada deverá, de imediato, notificar a outra para conhecimento desse fato, restabelecendo a situação original.</div>\n      </div>\n\n      <div class=\"clausula\">\n        <h2>X. Do Foro</h2>\n        <div class=\"corpo\">10.1. As partes, de comum acordo, elegem o foro da comarca de Ijuí/RS, para dirimir qualquer questão fundada no presente Contrato.</div>\n      </div>\n\n      <p>E por estarem de inteiro e comum acordo com as condições e com o texto deste Contrato, as partes o assinam, na presença das testemunhas signatárias.</p>\n\n      <div class=\"assinatura\">\n        <div class=\"local-data\" id=\"pv-local-data\"></div>\n        <div class=\"linha\">\n          <div class=\"bloco\">\n            <div class=\"traco\"></div>\n            <b id=\"pv-assinatura-nome\"></b>\n            <span id=\"pv-assinatura-doc\"></span>\n          </div>\n          <div class=\"bloco\">\n            <div class=\"traco\"></div>\n            <b>Vitor Henrique Mohr</b>\n            <span>03309589099</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<button class=\"print-btn\" onclick=\"window.print()\">Baixar PDF / Imprimir</button>\n\n<script>\nconst CAMPOS = {\n  objeto: 'in-objeto',\n  prestacao: 'in-prestacao',\n  prazo: 'in-prazo',\n  remuneracao: 'in-remuneracao',\n  obrigContratada: 'in-obrig-contratada',\n  obrigContratante: 'in-obrig-contratante',\n  rescisao: 'in-rescisao',\n  direitos: 'in-direitos',\n  contratante: 'in-contratante-paragrafo'\n};\nconst PREVIEWS = {\n  objeto: 'pv-objeto',\n  prestacao: 'pv-prestacao',\n  prazo: 'pv-prazo',\n  remuneracao: 'pv-remuneracao',\n  obrigContratada: 'pv-obrig-contratada',\n  obrigContratante: 'pv-obrig-contratante',\n  rescisao: 'pv-rescisao',\n  direitos: 'pv-direitos',\n  contratante: 'pv-contratante-paragrafo'\n};\n\nfunction valorFormatadoAtual(){\n  const v = document.getElementById('in-valor').value.trim();\n  return v ? ('R$ ' + v) : '{{VALOR}}';\n}\n\nfunction atualizarClausula(chave){\n  const texto = document.getElementById(CAMPOS[chave]).value;\n  const substituido = texto.split('{{VALOR}}').join(valorFormatadoAtual());\n  document.getElementById(PREVIEWS[chave]).textContent = substituido;\n}\n\nfunction atualizarTodasClausulas(){\n  Object.keys(CAMPOS).forEach(atualizarClausula);\n}\n\nfunction atualizarValor(){\n  atualizarClausula('remuneracao');\n}\n\nfunction atualizarAssinatura(){\n  document.getElementById('pv-assinatura-nome').textContent = document.getElementById('in-contratante-nome').value;\n  document.getElementById('pv-assinatura-doc').textContent = document.getElementById('in-contratante-doc').value;\n  const cidade = document.getElementById('in-cidade').value;\n  const data = document.getElementById('in-data-assinatura').value;\n  document.getElementById('pv-local-data').textContent = (cidade ? cidade + ', ' : '') + data + '.';\n}\n\n/* ---------------- Templates por tipo ---------------- */\n\nconst TEMPLATES = {\n  podcast: {\n    objeto: 'O presente contrato tem por objeto a prestação de serviços profissionais para captação e edição de podcasts em áudio e vídeo.',\n    prestacao: `2.1. Os serviços serão prestados conforme acordado previamente entre as partes. O escopo previsto para as atividades técnicas a serem realizadas pela CONTRATADA apresenta as seguintes características:\n\na) Captação e edição:\n- As captações serão realizadas em 1 (uma) diária mensal;\n- Captação e edição de 2 (dois) episódios mensais de podcast em vídeo, realizados na mesma diária de gravação;\n\nb) Da parte técnica:\n- Captação de áudio com até 6 (seis) participantes microfonados simultaneamente;\n- Captação em vídeo com 2 (duas) câmeras com resolução Full HD (1920x1080px);\n\nc) Extração de trechos para redes sociais:\n- Separação e exportação de trechos brutos dos episódios gravados, conforme orientação e definição prévia da CONTRATANTE;\n- Os arquivos serão entregues sem edição criativa, legendagem, identidade visual ou tratamento específico para redes sociais, ficando tais etapas sob responsabilidade da equipe de social media da CONTRATANTE;\n\nd) Armazenamento e backup:\n- Envio e aprovação dos materiais via Google Drive, bem como o armazenamento dos episódios finalizados.\n\n2.2. Quaisquer alterações na quantidade de episódios, diárias de gravação ou escopo dos serviços deverão ser previamente acordadas entre as partes e podem estar sujeitas a custos adicionais.`,\n    prazo: '3.1. O presente Contrato terá sua vigência a partir da assinatura das Partes e vigorará até a conclusão da prestação dos serviços contratados pela duração de 6 (seis) meses.',\n    remuneracao: `4.1. Pela prestação dos serviços descritos neste contrato, a CONTRATANTE pagará à CONTRATADA o valor mensal de {{VALOR}}, durante a vigência do contrato.\n4.2. O pagamento será realizado de forma mensal, por meio de boleto bancário, com vencimento todo dia 10 (dez) de cada mês.\n4.3. O pagamento não está condicionado à emissão, envio ou apresentação de Nota Fiscal, tampouco à entrega, aprovação ou aceite dos materiais produzidos no respectivo período.\n4.4. Todos os tributos, taxas, seguros, contribuições previdenciárias e quaisquer outras que venham a incidir sobre esta prestação de Serviços, estão incluídos no preço indicado no item anterior.`,\n    obrigContratada: `5.1. Prestar os serviços descritos neste Contrato dentro da melhor técnica, por intermédio de profissionais comprovadamente habilitados e capacitados;\n5.2. Prestar os serviços descritos neste Contrato, nos prazos acordados e conforme as características previamente estabelecidas;\n5.3. Informar à CONTRATANTE sempre que tiver conhecimento de algum fato ou situação que possa impactar ou reduzir a sua capacidade na prestação dos serviços ora contratados;\n5.4. Responsabilizar-se tecnicamente pela execução dos serviços contratados, não sendo responsável pelo conteúdo editorial, falas, opiniões, informações ou declarações emitidas pelos participantes do podcast, que são de inteira responsabilidade da CONTRATANTE;\n5.5. Realizar 01 (uma) rodada de alterações nos materiais entregues, desde que tais ajustes sejam solicitados de forma objetiva, dentro do escopo contratado e em prazo razoável após a entrega;\n5.6. Solicitações adicionais de alterações, refações ou ajustes que ultrapassem a rodada prevista no item anterior estarão sujeitas à cobrança adicional correspondente a 20% do valor mensal vigente, mediante prévia aprovação da CONTRATANTE;\n5.7. Submeter a versão final dos materiais para validação da CONTRATANTE, após a conclusão da rodada de alterações prevista neste contrato.`,\n    obrigContratante: `6.1. Além das demais obrigações previstas neste Contrato, competirá à CONTRATANTE:\n\na) Fornecer, à CONTRATADA, todas as informações necessárias à execução dos serviços objeto do presente instrumento;\n\nb) Realizar os pagamentos dos serviços prestados, de acordo com os prazos e valores previamente estabelecidos, em atendimento ao disposto no presente instrumento.`,\n    rescisao: `7.1. O presente contrato poderá ser rescindido pelas partes nas seguintes situações:\na) Por inadimplência de qualquer das partes, caso não sejam sanadas as pendências em até 10 (dez) dias após notificação formal da parte lesada;\nb) Por decisão de autoridade regulatória que impeça a continuidade dos serviços;\nc) Em razão de caso fortuito ou força maior que inviabilize a prestação dos serviços;\nd) Pela manifestação de interesse de qualquer das partes, mediante aviso prévio de 30 (trinta) dias.\n7.2. No caso de rescisão antecipada por iniciativa da CONTRATANTE, esta deverá realizar o pagamento proporcional aos serviços já prestados até a data da rescisão.\n7.3. Caso o cancelamento ocorra antes da captação dos episódios do período vigente, a CONTRATANTE deverá arcar com 50% do valor mensal como indenização por custos operacionais já comprometidos.\n7.4. Se a rescisão ocorrer após a captação e antes da entrega dos vídeos editados, a CONTRATANTE deverá realizar o pagamento integral referente ao período vigente.\n7.5. Em caso de rescisão por parte da CONTRATADA sem justificativa plausível, esta deverá reembolsar valores pagos antecipadamente pela CONTRATANTE.`,\n    direitos: `8.1. Os materiais produzidos em decorrência da execução do presente Contrato serão de propriedade da CONTRATANTE, que detém o direito de utilização dos conteúdos para fins institucionais, promocionais e comerciais, sem limitação territorial ou temporal.\n8.2. Fica expressamente autorizado à CONTRATADA o direito de utilizar, reproduzir e divulgar os materiais produzidos no âmbito deste Contrato, total ou parcialmente, exclusivamente para fins de portfólio, divulgação institucional, promoção de seus serviços e comprovação de capacidade técnica, em seus canais de comunicação, incluindo site, redes sociais, apresentações comerciais e propostas, sem qualquer ônus adicional à CONTRATANTE.\n8.3. A utilização dos materiais pela CONTRATADA, nos termos do item anterior, não caracteriza cessão comercial, revenda ou exploração econômica direta do conteúdo, limitando-se às finalidades institucionais e promocionais de seus serviços.\n8.4. A CONTRATADA declara e garante que a execução dos serviços técnicos objeto deste Contrato não infringe direitos autorais, patrimoniais ou de propriedade intelectual de terceiros, respondendo apenas pelos aspectos técnicos da produção, não sendo responsável pelo conteúdo editorial, falas ou informações fornecidas pelos participantes.`\n  },\n\n  recorrente: {\n    objeto: `1.1. O presente contrato tem por objeto a prestação de serviços profissionais de produção mensal de conteúdo audiovisual, consistindo na criação, captação, edição e entrega de até 08 (oito) vídeos por mês, no formato vertical, destinados à publicação em Reels do Instagram e demais plataformas de vídeo curto, conforme estratégia previamente alinhada entre as partes.\n\n1.2. A periodicidade das gravações, formatos dos vídeos, duração média e abordagem criativa serão definidos em comum acordo, respeitando os limites técnicos e criativos do plano contratado.`,\n    prestacao: `2.1. Os serviços serão prestados conforme acordado previamente entre as partes. O escopo previsto para as atividades técnicas a serem realizadas pela CONTRATADA apresenta as seguintes características:\n\na) Captação:\n- As captações de imagens serão realizadas em diárias, com datas a serem definidas previamente entre as partes;\n- As gravações poderão ocorrer nas dependências do CONTRATANTE ou em outros locais previamente alinhados, sem definição de locação fixa.\n\nb) Da parte técnica:\n- Será utilizada estrutura profissional de gravação, incluindo câmera com resolução mínima de 4K (3840x2160px), microfone sem fio, teleprompter e kit de iluminação, conforme a necessidade de cada produção.\n\nc) Edição e alterações:\n- A entrega da primeira versão dos vídeos editados será realizada em até 05 (cinco) dias úteis após a data da captação;\n- Estão inclusas até 02 (duas) rodadas de alterações, mediante envio de feedback pelo CONTRATANTE;\n- Alterações adicionais às rodadas previstas serão cobradas à parte, no valor correspondente a 5% (cinco por cento) do valor mensal do contrato, por rodada extra.\n\nd) Armazenamento e backup:\n- Os materiais finais serão enviados e aprovados por meio do Google Drive ou plataforma similar;\n- A CONTRATADA se responsabiliza pelo armazenamento e backup exclusivamente dos vídeos finais editados, pelo período em que o contrato estiver vigente;\n- Não está incluso o armazenamento ou backup dos arquivos brutos após a entrega e aprovação dos materiais finais.\n\n2.2. Quaisquer alterações na quantidade de entregáveis, diárias de gravação ou escopo dos serviços deverão ser previamente acordadas entre as partes, podendo implicar em ajustes de prazo e custos adicionais.`,\n    prazo: `3.1. O presente Contrato terá vigência de 06 (seis) meses, contados a partir da data de sua assinatura pelas partes.\n3.2. Findo o prazo de vigência, o contrato poderá ser renovado automaticamente por igual período, mediante concordância entre as partes.\n3.3. Em caso de renovação, os valores poderão ser reajustados, mediante comunicação prévia da CONTRATADA ao CONTRATANTE, considerando atualização de tabela, inflação, custos operacionais ou reposicionamento de mercado.\n3.4. A ausência de manifestação contrária de qualquer das partes até o término da vigência será interpretada como concordância com a renovação e com os valores atualizados.`,\n    remuneracao: `4.1. Pela prestação dos serviços descritos neste contrato, a CONTRATANTE pagará à CONTRATADA o valor mensal de {{VALOR}}.\n4.2. O pagamento será realizado mensalmente, todo dia 10 (dez) de cada mês, por meio de boleto bancário, emitido pela CONTRATADA e enviado previamente à CONTRATANTE juntamente com a respectiva Nota Fiscal de prestação de serviços.\n4.3. Todos os tributos, taxas, contribuições e quaisquer encargos que incidam ou venham a incidir sobre a prestação dos serviços ora contratados estão inclusos no valor mensal estabelecido na cláusula 4.1.`,\n    obrigContratada: `5.1. Além das demais obrigações previstas neste Contrato, competirá à CONTRATADA:\na) Prestar os serviços descritos neste Contrato dentro da melhor técnica, por intermédio de profissionais comprovadamente habilitados e capacitados;\nb) Prestar os serviços descritos neste Contrato, nos prazos acordados e conforme as características pré-estabelecidas;\nc) Informar à CONTRATANTE sempre que tiver conhecimento de algum fato ou situação que possa impactar ou reduzir a sua capacidade na prestação dos Serviços ora contratados;\nd) A CONTRATADA não se responsabiliza por informações, dados, roteiros ou orientações fornecidas pela CONTRATANTE, sendo esta integralmente responsável pelo conteúdo informativo, institucional ou promocional veiculado nos materiais produzidos;\ne) Validar as versões finais dos serviços prestados com a CONTRATANTE, antes de sua finalização.`,\n    obrigContratante: `6.1. Além das demais obrigações previstas neste Contrato, competirá à CONTRATANTE:\na) Fornecer, à CONTRATADA, todas as informações necessárias à execução dos serviços objeto do presente instrumento;\nb) Realizar os pagamentos dos serviços prestados, de acordo com os prazos e valores previamente estabelecidos, em atendimento ao disposto no presente instrumento.`,\n    rescisao: `7.1. O presente contrato poderá ser rescindido pelas partes nas seguintes situações:\na) Por inadimplência de qualquer das partes, caso não sejam sanadas as pendências em até 10 (dez) dias após notificação formal da parte lesada;\nb) Por decisão de autoridade regulatória que impeça a continuidade dos serviços;\nc) Em razão de caso fortuito ou força maior que inviabilize a prestação dos serviços;\nd) Pela manifestação de interesse de qualquer das partes, mediante aviso prévio de 30 (trinta) dias.\n7.2. No caso de rescisão antecipada por iniciativa da CONTRATANTE, esta deverá realizar o pagamento proporcional aos serviços já prestados até a data da rescisão.\n7.3. Em caso de rescisão antes do início da prestação dos serviços no período mensal vigente, a CONTRATANTE deverá arcar com 30% (trinta por cento) do valor mensal, a título de custos operacionais e bloqueio de agenda.\n7.4. Caso a rescisão ocorra após o início da prestação dos serviços no mês vigente, o valor mensal será devido de forma integral.\n7.5. Em caso de rescisão por parte da CONTRATADA sem justificativa plausível, esta deverá reembolsar valores pagos antecipadamente pela CONTRATANTE.`,\n    direitos: `8.1. Serão de propriedade da CONTRATANTE todos os direitos de uso e veiculação do conteúdo audiovisual resultante da execução deste contrato, incluindo os arquivos finais editados.\n8.2. A CONTRATADA declara e garante que o produto ou resultado da execução do presente contrato não infringe os direitos autorais, patrimoniais, propriedade intelectual de terceiros ou outros direitos protegidos pela legislação brasileira.\n8.3. A CONTRATADA poderá utilizar trechos ou versões resumidas do conteúdo produzido para fins de divulgação institucional, promoção de portfólio em redes sociais, sites ou apresentações comerciais, desde que não exponha informações sigilosas ou comprometa a imagem da CONTRATANTE.\n8.4. Na hipótese de contestação de direitos autorais ou patrimoniais por terceiros, caberá à CONTRATADA tomar todas as providências necessárias, por sua conta e risco, visando a defesa de seus direitos e os da CONTRATANTE. Caso a CONTRATANTE tenha que adotar medidas jurídicas, a CONTRATADA será responsável por todos os custos envolvidos, incluindo honorários advocatícios e eventuais indenizações.`\n  },\n\n  institucional: {\n    objeto: '1.1. O presente contrato tem por objeto a prestação de serviços profissionais para captação e edição de 1 (um) vídeo institucional, conforme escopo e características descritos neste instrumento.',\n    prestacao: `2.1. Os serviços serão prestados conforme acordado previamente entre as partes. O escopo previsto para as atividades técnicas a serem realizadas pela CONTRATADA apresenta as seguintes características:\n\na) Captação:\n- Captação com câmera com resolução mínima de 4K (3840x2160px);\n- Captação de imagens aéreas com drone, quando aplicável ao roteiro aprovado;\n- Locução/narração profissional, quando prevista no roteiro.\n\nb) Roteiro:\n- Elaboração de roteiro completo (texto + sugestão de imagens/cenas) para aprovação prévia da CONTRATANTE, antes do início da captação.\n\nc) Edição e alterações:\n- Entrega da primeira versão do vídeo editado em até 15 (quinze) dias corridos após a data da captação;\n- Está inclusa 01 (uma) rodada de alterações, desde que solicitada de forma objetiva e dentro do escopo aprovado;\n- Alterações adicionais à rodada prevista serão cobradas à parte, no valor correspondente a 10% (dez por cento) do valor total do projeto, por rodada extra.\n\nd) Armazenamento e backup:\n- Envio e aprovação do material final via Google Drive, bem como o armazenamento do vídeo finalizado.\n\n2.2. Quaisquer alterações no escopo, roteiro ou diárias de captação deverão ser previamente acordadas entre as partes e podem estar sujeitas a custos adicionais.`,\n    prazo: \"3.1. O presente Contrato vigorará a partir da assinatura das Partes até a entrega final do material contratado, prevista no item 2.1, 'c'.\",\n    remuneracao: `4.1. Pela prestação dos serviços descritos neste contrato, a CONTRATANTE pagará à CONTRATADA o valor total de {{VALOR}}.\n4.2. O pagamento será realizado em 2 (duas) parcelas: 50% (cinquenta por cento) na assinatura deste Contrato e 50% (cinquenta por cento) na entrega do material final.\n4.3. Todos os tributos, taxas, seguros, contribuições previdenciárias e quaisquer outras que venham a incidir sobre esta prestação de serviços estão incluídos no valor indicado no item anterior.`,\n    obrigContratada: `5.1. Prestar os serviços descritos neste Contrato dentro da melhor técnica, por intermédio de profissionais comprovadamente habilitados e capacitados;\n5.2. Prestar os serviços descritos neste Contrato, nos prazos acordados e conforme as características previamente estabelecidas;\n5.3. Informar à CONTRATANTE sempre que tiver conhecimento de algum fato ou situação que possa impactar ou reduzir a sua capacidade na prestação dos serviços ora contratados;\n5.4. Responsabilizar-se tecnicamente pela execução dos serviços contratados, não sendo responsável pelo conteúdo editorial, informações ou declarações fornecidas pela CONTRATANTE, que são de sua inteira responsabilidade;\n5.5. Submeter a versão final do material para validação da CONTRATANTE, após a conclusão da rodada de alterações prevista neste contrato.`,\n    obrigContratante: `6.1. Além das demais obrigações previstas neste Contrato, competirá à CONTRATANTE:\na) Fornecer, à CONTRATADA, todas as informações necessárias à execução dos serviços objeto do presente instrumento;\nb) Aprovar o roteiro previamente à captação, dentro de prazo razoável, sob pena de impacto no cronograma de entrega;\nc) Realizar os pagamentos dos serviços prestados, de acordo com os prazos e valores previamente estabelecidos, em atendimento ao disposto no presente instrumento.`,\n    rescisao: `7.1. O presente contrato poderá ser rescindido pelas partes nas seguintes situações:\na) Por inadimplência de qualquer das partes, caso não sejam sanadas as pendências em até 10 (dez) dias após notificação formal da parte lesada;\nb) Por decisão de autoridade regulatória que impeça a continuidade dos serviços;\nc) Em razão de caso fortuito ou força maior que inviabilize a prestação dos serviços;\nd) Pela manifestação de interesse de qualquer das partes, mediante aviso prévio de 30 (trinta) dias.\n7.2. No caso de rescisão antecipada por iniciativa da CONTRATANTE, esta deverá realizar o pagamento proporcional aos serviços já prestados até a data da rescisão.\n7.3. Caso o cancelamento ocorra antes da captação, a CONTRATANTE deverá arcar com 50% (cinquenta por cento) do valor total do projeto, como indenização por custos operacionais já comprometidos.\n7.4. Se a rescisão ocorrer após a captação e antes da entrega do vídeo editado, a CONTRATANTE deverá realizar o pagamento integral do valor total do projeto.\n7.5. Em caso de rescisão por parte da CONTRATADA sem justificativa plausível, esta deverá reembolsar valores pagos antecipadamente pela CONTRATANTE.`,\n    direitos: `8.1. Os materiais produzidos em decorrência da execução do presente Contrato serão de propriedade da CONTRATANTE, que detém o direito de utilização dos conteúdos para fins institucionais, promocionais e comerciais, sem limitação territorial ou temporal.\n8.2. Fica expressamente autorizado à CONTRATADA o direito de utilizar, reproduzir e divulgar os materiais produzidos no âmbito deste Contrato, total ou parcialmente, exclusivamente para fins de portfólio, divulgação institucional, promoção de seus serviços e comprovação de capacidade técnica, em seus canais de comunicação, incluindo site, redes sociais, apresentações comerciais e propostas, sem qualquer ônus adicional à CONTRATANTE.\n8.3. A utilização dos materiais pela CONTRATADA, nos termos do item anterior, não caracteriza cessão comercial, revenda ou exploração econômica direta do conteúdo, limitando-se às finalidades institucionais e promocionais de seus serviços.\n8.4. A CONTRATADA declara e garante que a execução dos serviços técnicos objeto deste Contrato não infringe direitos autorais, patrimoniais ou de propriedade intelectual de terceiros, respondendo apenas pelos aspectos técnicos da produção.`\n  }\n};\n\nfunction aplicarTemplateTipo(){\n  const tipo = document.getElementById('in-tipo-contrato').value;\n  const modelo = TEMPLATES[tipo];\n  if (!modelo) return;\n  document.getElementById('in-objeto').value = modelo.objeto;\n  document.getElementById('in-prestacao').value = modelo.prestacao;\n  document.getElementById('in-prazo').value = modelo.prazo;\n  document.getElementById('in-remuneracao').value = modelo.remuneracao;\n  document.getElementById('in-obrig-contratada').value = modelo.obrigContratada;\n  document.getElementById('in-obrig-contratante').value = modelo.obrigContratante;\n  document.getElementById('in-rescisao').value = modelo.rescisao;\n  document.getElementById('in-direitos').value = modelo.direitos;\n  atualizarTodasClausulas();\n}\n\n/* ---------------- Cliente / contratante ---------------- */\n\nlet listaClientes = [];\n\nfunction popularSelectClientes(){\n  const sel = document.getElementById('in-cliente-selecionar');\n  if (!sel) return;\n  sel.innerHTML = '<option value=\"\">— Selecionar —</option>';\n  listaClientes.forEach((c, idx)=>{\n    const opt = document.createElement('option');\n    opt.value = String(idx);\n    opt.textContent = c.nome || '(sem nome)';\n    sel.appendChild(opt);\n  });\n}\n\nfunction gerarParagrafoContratante(c){\n  const doc = (c.cnpj || '').replace(/\\D/g, '');\n  const isPJ = doc.length > 11;\n  const enderecoCompleto = [c.endereco, c.bairro, [c.municipio, c.estado].filter(Boolean).join('/')].filter(Boolean).join(', ');\n  if (isPJ){\n    return (c.razaoSocial || c.nome) + ', pessoa jurídica de direito privado, inscrita no CNPJ sob o nº ' + (c.cnpj || '') +\n      (enderecoCompleto ? ', com sede na ' + enderecoCompleto : '') +\n      (c.cep ? ', CEP ' + c.cep : '') + ', doravante denominada CONTRATANTE.';\n  }\n  return (c.nome || '') + ', inscrita no CPF sob o nº ' + (c.cnpj || '') +\n    (enderecoCompleto ? ', residente e domiciliada na ' + enderecoCompleto : '') +\n    ', doravante denominada CONTRATANTE.';\n}\n\nfunction aplicarCliente(c){\n  document.getElementById('in-contratante-nome').value = c.razaoSocial || c.nome || '';\n  document.getElementById('in-contratante-doc').value = c.cnpj || '';\n  document.getElementById('in-contratante-paragrafo').value = gerarParagrafoContratante(c);\n  atualizarClausula('contratante');\n  atualizarAssinatura();\n}\n\nfunction preencherClienteSelecionado(){\n  const sel = document.getElementById('in-cliente-selecionar');\n  const idx = sel.value;\n  if (idx === '') return;\n  const c = listaClientes[Number(idx)];\n  if (!c) return;\n  aplicarCliente(c);\n}\n\n/* ---------------- Importar de proposta ---------------- */\n\nfunction mapearTipoProposta(tipoProposta){\n  const t = (tipoProposta || '').toLowerCase();\n  if (t.indexOf('podcast') !== -1) return 'podcast';\n  if (t.indexOf('institucional') !== -1) return 'institucional';\n  if (t.indexOf('conteúdo') !== -1 || t.indexOf('conteudo') !== -1 || t.indexOf('recorrente') !== -1 || t.indexOf('social') !== -1) return 'recorrente';\n  return 'institucional';\n}\n\nfunction aplicarImportacao(dados){\n  if (!dados) return;\n  if (dados.tipo){\n    const tipoMapeado = mapearTipoProposta(dados.tipo);\n    document.getElementById('in-tipo-contrato').value = tipoMapeado;\n    aplicarTemplateTipo();\n  }\n  if (dados.valor){\n    document.getElementById('in-valor').value = Number(dados.valor).toLocaleString('pt-BR', {minimumFractionDigits:2});\n    atualizarValor();\n  }\n  if (dados.clienteId && listaClientes.length){\n    const c = listaClientes.find((cl) => cl.id === dados.clienteId);\n    if (c) aplicarCliente(c);\n  }\n}\n\n/* ---------------- Comunicação com o painel ---------------- */\n\nwindow.addEventListener('message', (event)=>{\n  const msg = event.data;\n  if (!msg || typeof msg !== 'object' || msg.type !== 'fuzz:init-contrato') return;\n  const payload = msg.payload || {};\n  if (Array.isArray(payload.clientes)){\n    listaClientes = payload.clientes;\n    popularSelectClientes();\n  }\n  if (payload.importar) aplicarImportacao(payload.importar);\n});\n\n/* ---------------- Init ---------------- */\n\nfunction hojeFormatado(){\n  const d = new Date();\n  const meses = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];\n  return d.getDate() + ' de ' + meses[d.getMonth()] + ' de ' + d.getFullYear();\n}\n\ndocument.getElementById('in-data-assinatura').value = hojeFormatado();\naplicarTemplateTipo();\natualizarAssinatura();\nwindow.parent.postMessage({ type: 'fuzz:contrato-pronto' }, '*');\n</script>\n</body>\n</html>\n";
